    'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки': 'Haier, Hartens, Sony, TCL, Kivi, DEXP, set-top boxes',
    'Откройте Настройки → «Настройки устройства» (на части моделей — «Система»).': 'Open Settings → “Device Preferences” (on some models — “System”).',
    'Зайдите в «Об устройстве».': 'Go to “About”.',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Highlight “Build” and press OK on the remote 7 times in a row — you’ll see “You are now a developer”.',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Go back: a new “Developer options” item has appeared. Open it.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Turn on “USB debugging”. If there is “Network debugging” or “ADB over network”, turn it on too.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Newer Sony, TCL, Hisense, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Settings → “System” → “About”.',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Press OK 7 times on “Android TV OS build”.',
    'Назад в «Система» → «Для разработчиков».': 'Back to “System” → “Developer options”.',
    'Включите «Отладка по USB».': 'Turn on “USB debugging”.',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'If the TV is not found: turn on “Wireless debugging” there too and in TVCleanzer tap “Connect with code” (the icon with digits at the top of the main screen).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'Pairing with a code is needed only once. Works on phones with Android 10 or newer (12+ is best) and on iPhone.',
    'Глобальная прошивка с PatchWall / Android TV': 'Global firmware with PatchWall / Android TV',
    'Настройки → «Настройки устройства» → «Об устройстве».': 'Settings → “Device Preferences” → “About”.',
    'Нажмите ОК 7 раз на строке «Сборка».': 'Press OK 7 times on “Build”.',
    'Назад → «Для разработчиков» → включите «Отладка по USB».': 'Back → “Developer options” → turn on “USB debugging”.',
    'Xiaomi Китай': 'Xiaomi China',
    'Redmi и Xiaomi с китайской прошивкой (HyperOS, MIUI TV)': 'Redmi and Xiaomi with Chinese firmware (HyperOS, MIUI TV)',
    'Настройки → «О телевизоре».': 'Settings → “About TV”.',
    'Нажмите ОК 7 раз на строке «Модель продукта».': 'Press OK 7 times on “Product model”.',
    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Back → “Account & Security” → turn on “ADB debugging”.',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'On these firmwares debugging turns off after every TV restart — turn it on before using TVCleanzer.',
    'Amazon Fire TV и телевизоры с Fire OS': 'Amazon Fire TV and TVs with Fire OS',
    'Настройки → «Моё Fire TV» → «О программе».': 'Settings → “My Fire TV” → “About”.',
    'Нажмите ОК 7 раз на названии устройства.': 'Press OK 7 times on the device name.',
    'Назад → «Для разработчиков» → включите «Отладка ADB».': 'Back → “Developer options” → turn on “ADB debugging”.',
    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'Fire OS doesn’t allow changing the home screen: clean-up and the remote work, our launcher doesn’t.',
    'Android TV и Google TV от Philips': 'Android TV and Google TV by Philips',
    'Проверьте Настройки → «Об устройстве»: если там есть версия Android (прошивка TPM…), делайте как для Android TV.': 'Check Settings → “About”: if it shows an Android version (TPM… firmware), follow the Android TV steps.',
    'Прошивки TPN… (Titan OS, Saphi) — не Android, с ними TVCleanzer не работает.': 'TPN… firmwares (Titan OS, Saphi) are not Android; TVCleanzer doesn’t work with them.',
    'а также Hisense VIDAA, Roku': 'as well as Hisense VIDAA, Roku',
