    'Отладки по сети на них нет, поэтому TVCleanzer с ними не работает.': 'They have no network debugging, so TVCleanzer doesn’t work with them.',
    'Как включить отладку': 'How to turn on debugging',
    'Выберите свой телевизор:': 'Choose your TV:',
    'Телефон и телевизор должны быть в одной Wi-Fi сети. При первом подключении на ТВ появится «Разрешить отладку?» — отметьте «Всегда разрешать» и нажмите «Разрешить».': 'Your phone and TV must be on the same Wi-Fi network. On the first connection the TV asks “Allow debugging?” — tick “Always allow” and tap “Allow”.',
