    'Чаевые разработчику: ничего не открывают и не продлеваются — просто спасибо за приложение.': 'Чайові розробнику: нічого не відкривають і не продовжуються — просто дякую за застосунок.',
    'Включать, когда телевизор простоит': 'Вмикати, коли телевізор простоїть',
    'Показать сейчас': 'Показати зараз',
    'Фоторамка запущена на телевизоре': 'Фоторамку запущено на телевізорі',
    'Телевизор не дал запустить заставку сразу: она включится сама, когда ТВ постоит без дела.': 'Телевізор не дав запустити заставку одразу: вона ввімкнеться сама, коли ТБ постоїть без діла.',
    'Автор — {0} · {1}': 'Автор — {0} · {1}',
    'TVCleanzer бесплатный и без рекламы. Если он вам помог — можно поддержать автора.': 'TVCleanzer безкоштовний і без реклами. Якщо він вам допоміг — можна підтримати автора.',
    'Поддержать автора': 'Підтримати автора',
    'Спасибо! Любая сумма помогает делать TVCleanzer дальше.': 'Дякуємо! Будь-яка сума допомагає розвивати TVCleanzer.',
    'Ссылка скопирована: {0}': 'Посилання скопійовано: {0}',
    '{0} мин': '{0} хв',
    '{0} с': '{0} с',
    'Ваши фото по очереди, с часами и погодой: когда телевизор простаивает, и, если хотите, фоном главного экрана. Включается только по вашему желанию.': 'Ваші фото по черзі, з годинником і погодою: коли телевізор простоює, і, якщо хочете, фоном головного екрана. Вмикається лише за вашим бажанням.',
    'Вернуть прежнюю заставку': 'Повернути попередню заставку',
    'До 30 фото. Они уменьшаются до 1920 пикселей и занимают немного места.': 'До 30 фото. Вони зменшуються до 1920 пікселів і займають небагато місця.',
    'Добавить фото': 'Додати фото',
    'Менять фон главного экрана': 'Змінювати фон головного екрана',
    'На телевизоре фото: {0}': 'Фото на телевізорі: {0}',
    'Отправляем фото {0} из {1}…': 'Надсилаємо фото {0} з {1}…',
    'Прежняя заставка возвращена': 'Попередню заставку повернуто',
    'Сделать заставкой телевизора': 'Зробити заставкою телевізора',
    'Сейчас заставка телевизора — фоторамка': 'Зараз заставка телевізора — фоторамка',
    'Смена фото': 'Зміна фото',
    'Сохранено': 'Збережено',
    'Удалить все': 'Видалити всі',
    'Фото добавлены: {0}': 'Фото додано: {0}',
    'Фото сменяют друг друга вместо одного фона': 'Фото змінюють одне одного замість одного фону',
    'Фото удалены': 'Фото видалено',
    'Фоторамка': 'Фоторамка',
    'Фоторамка включена: она появится, когда телевизор постоит без дела. Через сколько минут — задаётся в настройках ТВ, раздел «Заставка».': 'Фоторамку ввімкнено: вона з’явиться, коли телевізор постоїть без діла. Через скільки хвилин — задається в налаштуваннях ТБ, розділ «Заставка».',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+; на Android 5–6 — пробная поддержка).': 'Легкий і гарний лаунчер: годинник, обране, усі застосунки, скіни. Менше 100 КБ, працює навіть на слабких телевізорах (Android 7+; на Android 5–6 — пробна підтримка).',
    'Нужен Android 5 или новее на телевизоре (сейчас SDK {0}).': 'Потрібен Android 5 або новіший на телевізорі (зараз SDK {0}).',
    'Избранное на главном экране': 'Обране на головному екрані',
    'Один ряд': 'Один ряд',
