    'По 5': 'По 5',
    'По 6': 'По 6',
    'Погоду телевизор берёт с Open-Meteo или met.no раз в полчаса; о вас туда ничего не отправляется.': 'Погоду телевізор бере з Open-Meteo або met.no раз на пів години; про вас туди нічого не надсилається.',
    'Убираем PatchWall…': 'Прибираємо PatchWall…',
    'телевизор не может получить погоду: проверьте, что на нём есть интернет': 'телевізор не може отримати погоду: перевірте, що на ньому є інтернет',
    'Обычное приложение: уберите, если не пользуетесь': 'Звичайний застосунок: приберіть, якщо не користуєтеся',
    'Онлайн-кинотеатр: уберите, если нет подписки и не смотрите': 'Онлайн-кінотеатр: приберіть, якщо немає підписки й не дивитеся',
    'Музыка: уберите, если не слушаете музыку на телевизоре': 'Музика: приберіть, якщо не слухаєте музику на телевізорі',
    'Заставка, когда ТВ простаивает. Без неё будет просто тёмный экран': 'Заставка, коли ТБ простоює. Без неї буде просто темний екран',
    'Трансляция с телефона на ТВ: уберите, если не выводите видео с телефона': 'Трансляція з телефона на ТБ: приберіть, якщо не виводите відео з телефона',
    'YouTube: уберите, только если смотрите его в другом приложении': 'YouTube: приберіть, лише якщо дивитеся його в іншому застосунку',
    'Браузер: уберите, если не открываете сайты на телевизоре': 'Браузер: приберіть, якщо не відкриваєте сайти на телевізорі',
    'Плеер для видео: если после удаления что-то перестанет играть, верните его в «Истории»': 'Плеєр для відео: якщо після видалення щось перестане грати, поверніть його в «Історії»',
    'Файлы и плеер для флешки: уберите, если не смотрите видео с USB': 'Файли й плеєр для флешки: приберіть, якщо не дивитеся відео з USB',
    'Фото и видео с флешки: уберите, если не смотрите их на ТВ': 'Фото й відео з флешки: приберіть, якщо не переглядаєте їх на ТБ',
    'Часть Alexa: уберите, если не пользуетесь голосовым помощником Amazon': 'Частина Alexa: приберіть, якщо не користуєтеся голосовим помічником Amazon',
    'Камера: на телевизоре без камеры не нужна': 'Камера: на телевізорі без камери не потрібна',
    'Подключение часов и других гаджетов к ТВ; почти никому не нужно': 'Підключення годинника й інших ґаджетів до ТБ; майже нікому не потрібне',
    'Автонастройка прокси по PAC-файлу: нужна только в офисных сетях': 'Автоналаштування проксі за PAC-файлом: потрібне лише в офісних мережах',
    'Аккаунт производителя (CVTE): нужен только для его фирменных сервисов': 'Акаунт виробника (CVTE): потрібен лише для його фірмових сервісів',
    'Синхронизация контактов: на ТВ бесполезна': 'Синхронізація контактів: на ТБ марна',
    'Корпоративное управление устройством: дома не нужно': 'Корпоративне керування пристроєм: удома не потрібне',
    'Экстренные оповещения через сотовую сеть: на ТВ без SIM-карты не работают': 'Екстрені сповіщення через мобільну мережу: на ТБ без SIM-картки не працюють',
    'HbbTV: интерактивные кнопки эфирных каналов. Сами каналы работают и без него': 'HbbTV: інтерактивні кнопки ефірних каналів. Самі канали працюють і без нього',
    'Убирают в {0} из {1} списков чистки ТВ': 'Прибирають у {0} з {1} списків чистки ТБ',
    'Можно убрать: телевизор без этого работает': 'Можна прибрати: телевізор без цього працює',
    'На ваше усмотрение: уберите, только если не пользуетесь этой функцией': 'На ваш розсуд: приберіть, лише якщо не користуєтеся цією функцією',
    'Лучше оставить': 'Краще залишити',
    'Системное: TVCleanzer его не трогает': 'Системне: TVCleanzer його не чіпає',
    'Занимает {0} МБ': 'Займає {0} МБ',
    'Понятно': 'Зрозуміло',
    'Не знаете, что это? Нажмите на значок слева или удерживайте строку.': 'Не знаєте, що це? Натисніть на значок ліворуч або утримуйте рядок.',
    'Вид главного экрана': 'Вигляд головного екрана',
