    'Эти настройки появились в новой версии лаунчера: нажмите «Обновить лаунчер на ТВ» ниже.': 'Ці налаштування з’явилися в новій версії лаунчера: натисніть «Оновити лаунчер на ТБ» нижче.',
    'Слабый телевизор подтормаживает? Выключите анимации и живой фон.': 'Слабкий телевізор підгальмовує? Вимкніть анімації й живий фон.',
    'Есть новая версия лаунчера: тонкие настройки, живой фон, новые шкурки и надёжная загрузка фото. Нажмите «Обновить лаунчер на ТВ».': 'Є нова версія лаунчера: тонкі налаштування, живий фон, нові скіни й надійне завантаження фото. Натисніть «Оновити лаунчер на ТБ».',
    'Затемнение фото': 'Затемнення фото',
    'Затемнение работает в новой версии лаунчера: обновите его на вкладке «Лаунчер».': 'Затемнення працює в новій версії лаунчера: оновіть його на вкладці «Лаунчер».',
    'Лучше горизонтальное фото, 16:9. Затемнение помогает читать часы и названия на ярких снимках.': 'Найкраще горизонтальне фото 16:9. Затемнення допомагає читати годинник і назви на яскравих знімках.',
    'Отправляем фото на телевизор…': 'Надсилаємо фото на телевізор…',
    'Не удалось прочитать фото. Выберите другое.': 'Не вдалося прочитати фото. Виберіть інше.',
    'Фото не дошло до телевизора целиком. Попробуйте ещё раз.': 'Фото не дійшло до телевізора повністю. Спробуйте ще раз.',
    'Телевизор не дал сохранить фото. Обновите лаунчер на ТВ и попробуйте снова.': 'Телевізор не дав зберегти фото. Оновіть лаунчер на ТБ і спробуйте знову.',
    'Проекторы': 'Проєктори',
    'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — на Android TV и Google TV': 'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — на Android TV і Google TV',
    'На Google TV: если проектор не находится, включите там же «Беспроводная отладка» и подключите TVCleanzer по коду.': 'На Google TV: якщо проєктор не знаходиться, увімкніть там само «Бездротове налагодження» й підключіть TVCleanzer за кодом.',
    'Автотрапецию, фокус и настройки проекции TVCleanzer не трогает.': 'Автотрапецію, фокус і налаштування проєкції TVCleanzer не чіпає.',
    'Проекторы HY300': 'Проєктори HY300',
    'Magcubic, Allwinner, Rockchip и похожие китайские модели': 'Magcubic, Allwinner, Rockchip та схожі китайські моделі',
    'Откройте Настройки → «Other settings» (или «Система») → «Developer mode» / «Для разработчиков».': 'Відкрийте Налаштування → «Other settings» (або «Система») → «Developer mode» / «Для розробників».',
    'Включите «ADB debug» или «Отладка по USB». Если есть «Беспроводная отладка» — включите её и подключите TVCleanzer по коду.': 'Увімкніть «ADB debug» або «Налагодження USB». Якщо є «Бездротове налагодження» — увімкніть його й підключіть TVCleanzer за кодом.',
    'На многих таких проекторах отладка выключается после перезагрузки — включайте её перед работой с TVCleanzer. Автофокус и трапецию TVCleanzer не трогает.': 'На багатьох таких проєкторах налагодження вимикається після перезавантаження — вмикайте його перед роботою з TVCleanzer. Автофокус і трапецію TVCleanzer не чіпає.',
    'Полночь': 'Північ',
    'Аврора': 'Аврора',
    'Закат': 'Захід сонця',
    'Океан': 'Океан',
    'Графит': 'Графіт',
    'Лес': 'Ліс',
    'Связь с телевизором прервалась во время очистки.': 'Зв’язок із телевізором перервався під час очищення.',
