    'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки': 'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки',
    'Откройте Настройки → «Настройки устройства» (на части моделей — «Система»).': 'Відкрийте Налаштування → «Налаштування пристрою» (на деяких моделях — «Система»).',
    'Зайдите в «Об устройстве».': 'Зайдіть у «Про пристрій».',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Наведіть на рядок «Збірка» й натисніть OK на пульті 7 разів поспіль — з’явиться «Ви стали розробником».',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Поверніться назад: з’явився пункт «Для розробників». Відкрийте його.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Увімкніть «Налагодження через USB». Якщо є «Налагодження через мережу» або «ADB через мережу» — увімкніть і його.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Нові Sony, TCL, Hisense, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Налаштування → «Система» → «Про пристрій».',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Натисніть OK 7 разів на рядку «Збірка ОС Android TV».',
    'Назад в «Система» → «Для разработчиков».': 'Назад у «Система» → «Для розробників».',
    'Включите «Отладка по USB».': 'Увімкніть «Налагодження через USB».',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'Якщо телевізор не знаходиться: там же увімкніть «Бездротове налагодження» і в TVCleanzer натисніть «Підключити за кодом» (значок із цифрами вгорі головного екрана).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'Підключення за кодом потрібне один раз. Працює на телефонах з Android 10 і новіше (краще 12+) та на iPhone.',
    'Глобальная прошивка с PatchWall / Android TV': 'Глобальна прошивка з PatchWall / Android TV',
    'Настройки → «Настройки устройства» → «Об устройстве».': 'Налаштування → «Налаштування пристрою» → «Про пристрій».',
    'Нажмите ОК 7 раз на строке «Сборка».': 'Натисніть OK 7 разів на рядку «Збірка».',
