    'Redmi и Xiaomi с китайской прошивкой (HyperOS, MIUI TV)': 'Redmi і Xiaomi з китайською прошивкою (HyperOS, MIUI TV)',
    'Настройки → «О телевизоре».': 'Налаштування → «Про телевізор».',
    'Нажмите ОК 7 раз на строке «Модель продукта».': 'Натисніть OK 7 разів на рядку «Модель продукту».',
    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Назад → «Обліковий запис і безпека» → увімкніть «Налагодження ADB».',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'На цих прошивках налагодження вимикається після кожного перезапуску телевізора — вмикайте його перед роботою з TVCleanzer.',
    'Amazon Fire TV и телевизоры с Fire OS': 'Amazon Fire TV і телевізори з Fire OS',
    'Настройки → «Моё Fire TV» → «О программе».': 'Налаштування → «Мій Fire TV» → «Про програму».',
