    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'Fire OS не дає змінити головний екран: очищення й пульт працюють, наш лаунчер — ні.',
    'Android TV и Google TV от Philips': 'Android TV і Google TV від Philips',
