    'Как включить отладку': 'Як увімкнути налагодження',
    'Выберите свой телевизор:': 'Оберіть свій телевізор:',
    'Телефон и телевизор должны быть в одной Wi-Fi сети. При первом подключении на ТВ появится «Разрешить отладку?» — отметьте «Всегда разрешать» и нажмите «Разрешить».': 'Телефон і телевізор мають бути в одній мережі Wi-Fi. Під час першого підключення на ТБ з’явиться «Дозволити налагодження?» — позначте «Завжди дозволяти» й натисніть «Дозволити».',
