    'Анимации на «{0}» вернутся к прежней скорости. Телевизор должен быть включён и в той же Wi-Fi сети.': 'Анімації на «{0}» повернуться до попередньої швидкості. Телевізор має бути увімкнений і в тій самій мережі Wi-Fi.',
