    'Детский режим': 'Дитячий режим',
    'На ТВ останутся только выбранные приложения. Выйти — по PIN.': 'На ТБ залишаться лише вибрані застосунки. Вийти — за PIN.',
    'Новый PIN (необязательно)': 'Новий PIN (необов’язково)',
    'PIN для выхода (4–8 цифр)': 'PIN для виходу (4–8 цифр)',
    'Не настоящая блокировка: ребёнок, который знает про отладку, обойдёт её. Но от случайных приложений и рекламы — защитит.': 'Не справжнє блокування: дитина, яка знає про налагодження, обійде його. Але від випадкових застосунків і реклами захистить.',
    'ЧТО МОЖНО ДЕТЯМ': 'ЩО МОЖНА ДІТЯМ',
    'Сначала придумайте PIN из 4–8 цифр — без него из детского режима не выйти.': 'Спершу придумайте PIN із 4–8 цифр — без нього з дитячого режиму не вийти.',
