    'Выберите телевизор на вкладке «Очистка».': 'Оберіть телевізор на вкладці «Очищення».',
    'Узнаем, какой лаунчер сейчас главный на «{0}».': 'Дізнаємося, який лаунчер зараз головний на «{0}».',
    'Главный лаунчер не выбран: телевизор спрашивает при нажатии «Домой».': 'Головний лаунчер не вибрано: телевізор питає під час натискання «Додому».',
    'Лаунчер производителя ({0})': 'Лаунчер виробника ({0})',
    'Сейчас на телевизоре': 'Зараз на телевізорі',
    'Обновить': 'Оновити',
    'Проверить': 'Перевірити',
    'установлен': 'встановлено',
    'не установлен': 'не встановлено',
    'Шкурка меняется сразу: просто выберите другую выше. На телевизоре: долгое нажатие OK на приложении — добавить в избранное, переставить или скрыть; шестерёнка — настройки.': 'Скін змінюється одразу: просто виберіть інший вище. На телевізорі: довге натискання OK на застосунку — додати в обране, переставити чи приховати; шестірня — налаштування.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+).': 'Легкий і гарний лаунчер: годинник, обране, усі застосунки, скіни. Менше 100 КБ, працює навіть на слабких телевізорах (Android 7+).',
    'Настроить: избранное, детям, обои': 'Налаштувати: обране, дітям, шпалери',
    'Обновить лаунчер на ТВ': 'Оновити лаунчер на ТБ',
    'Вернуть стандартный лаунчер': 'Повернути стандартний лаунчер',
    'Установить на телевизор': 'Встановити на телевізор',
    'Приложения': 'Застосунки',
    'Введите адрес как на экране ТВ, например 192.168.1.20:37155': 'Введіть адресу як на екрані ТБ, наприклад 192.168.1.20:37155',
    'Код — 6 цифр из окна «Подключение по коду».': 'Код — 6 цифр із вікна «Підключення за кодом».',
    'Сопряжение не удалось: {0}': 'Сполучення не вдалося: {0}',
    'Введите IP-адрес и порт с экрана «Беспроводная отладка».': 'Введіть IP-адресу й порт з екрана «Бездротове налагодження».',
    'Не удалось подключиться. Проверьте порт: он на главном экране «Беспроводной отладки» и отличается от порта сопряжения.': 'Не вдалося підключитися. Перевірте порт: він на головному екрані «Бездротового налагодження» і відрізняється від порту сполучення.',
    'Сопряжение': 'Сполучення',
    'На ТВ: Настройки → Для разработчиков → Беспроводная отладка → ВКЛ → «Подключить устройство с помощью кода». Введите адрес и код из этого окна.': 'На ТБ: Налаштування → Для розробників → Бездротове налагодження → УВІМК → «Підключити пристрій за допомогою коду». Введіть адресу й код із цього вікна.',
    'IP-адрес и порт': 'IP-адреса й порт',
    'Код': 'Код',
    '6 цифр': '6 цифр',
    'Подключение': 'Підключення',
    'Готово, телефон сопряжён. Окно с кодом можно закрыть. На главном экране «Беспроводной отладки» указан IP-адрес и порт — введите их.': 'Готово, телефон сполучено. Вікно з кодом можна закрити. На головному екрані «Бездротового налагодження» вказано IP-адресу й порт — введіть їх.',
    'Сопрячь': 'Сполучити',
