    'Прошивка не даёт убрать их с телефона. Нажмите «Открыть на ТВ» и на телевизоре выберите «Отключить».': 'El firmware no deja quitarlas desde el móvil. Pulsa «Abrir en la TV» y en el televisor elige «Desactivar».',
    'На телевизоре открылись настройки приложения: выберите «Отключить».': 'En la TV se abrieron los ajustes de la app: elige «Desactivar».',
    'Не получилось открыть настройки на ТВ': 'No se pudieron abrir los ajustes en la TV',
    'Спасибо! Это очень помогает делать TVCleanzer дальше.': '¡Gracias! Esto ayuda mucho a seguir con TVCleanzer.',
    'Чаевые разработчику: ничего не открывают и не продлеваются — просто спасибо за приложение.': 'Una propina para el desarrollador: no desbloquea nada ni se renueva, solo es un agradecimiento por la app.',
    'Включать, когда телевизор простоит': 'Activar cuando la TV lleve inactiva',
    'Показать сейчас': 'Mostrar ahora',
    'Фоторамка запущена на телевизоре': 'El marco de fotos se está mostrando en la TV',
    'Телевизор не дал запустить заставку сразу: она включится сама, когда ТВ постоит без дела.': 'La TV no permitió iniciar el salvapantallas ahora: se iniciará solo cuando la TV esté inactiva.',
    'Автор — {0} · {1}': 'Autor: {0} · {1}',
    'TVCleanzer бесплатный и без рекламы. Если он вам помог — можно поддержать автора.': 'TVCleanzer es gratis y sin anuncios. Si te ha ayudado, puedes apoyar al autor.',
    'Поддержать автора': 'Apoyar al autor',
    'Спасибо! Любая сумма помогает делать TVCleanzer дальше.': '¡Gracias! Cualquier cantidad ayuda a seguir con TVCleanzer.',
    'Ссылка скопирована: {0}': 'Enlace copiado: {0}',
    '{0} мин': '{0} min',
    '{0} с': '{0} s',
    'Ваши фото по очереди, с часами и погодой: когда телевизор простаивает, и, если хотите, фоном главного экрана. Включается только по вашему желанию.': 'Tus fotos una tras otra, con la hora y el tiempo: cuando la TV está inactiva y, si quieres, como fondo de la pantalla principal. Solo se activa si lo deseas.',
    'Вернуть прежнюю заставку': 'Restaurar el salvapantallas anterior',
    'До 30 фото. Они уменьшаются до 1920 пикселей и занимают немного места.': 'Hasta 30 fotos. Se reducen a 1920 píxeles y ocupan poco espacio.',
    'Добавить фото': 'Añadir fotos',
    'Менять фон главного экрана': 'Cambiar el fondo de la pantalla principal',
    'На телевизоре фото: {0}': 'Fotos en la TV: {0}',
    'Отправляем фото {0} из {1}…': 'Enviando foto {0} de {1}…',
    'Прежняя заставка возвращена': 'Se restauró el salvapantallas anterior',
    'Сделать заставкой телевизора': 'Usar como salvapantallas de la TV',
    'Сейчас заставка телевизора — фоторамка': 'El salvapantallas de la TV es ahora el marco de fotos',
    'Смена фото': 'Cambio de foto',
    'Сохранено': 'Guardado',
    'Удалить все': 'Borrar todas',
    'Фото добавлены: {0}': 'Fotos añadidas: {0}',
    'Фото сменяют друг друга вместо одного фона': 'Las fotos se turnan en lugar de un solo fondo',
    'Фото удалены': 'Fotos borradas',
    'Фоторамка': 'Marco de fotos',
    'Фоторамка включена: она появится, когда телевизор постоит без дела. Через сколько минут — задаётся в настройках ТВ, раздел «Заставка».': 'Marco de fotos activado: aparece cuando la TV lleva un rato inactiva. Los minutos se ajustan en los ajustes de la TV, sección Salvapantallas.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+; на Android 5–6 — пробная поддержка).': 'Un launcher ligero y bonito: reloj, favoritos, todas las apps, temas. Menos de 100 KB, funciona incluso en TVs modestas (Android 7+; Android 5–6 en pruebas).',
    'Нужен Android 5 или новее на телевизоре (сейчас SDK {0}).': 'La TV necesita Android 5 o posterior (ahora SDK {0}).',
    'Избранное на главном экране': 'Favoritos en la pantalla principal',
    'Один ряд': 'Una fila',
    'По 4': '4 por fila',
    'По 5': '5 por fila',
    'По 6': '6 por fila',
    'Погоду телевизор берёт с Open-Meteo или met.no раз в полчаса; о вас туда ничего не отправляется.': 'La TV obtiene el tiempo de Open-Meteo o met.no cada media hora; no se envía nada sobre ti.',
    'Убираем PatchWall…': 'Quitando PatchWall…',
    'телевизор не может получить погоду: проверьте, что на нём есть интернет': 'la TV no puede obtener el tiempo: comprueba que tenga internet',
    'Обычное приложение: уберите, если не пользуетесь': 'App normal: quítala si no la usas',
    'Онлайн-кинотеатр: уберите, если нет подписки и не смотрите': 'Servicio de streaming: quítalo si no tienes suscripción ni lo ves',
    'Музыка: уберите, если не слушаете музыку на телевизоре': 'Música: quítala si no escuchas música en la TV',
    'Заставка, когда ТВ простаивает. Без неё будет просто тёмный экран': 'Salvapantallas cuando la TV está inactiva. Sin él, la pantalla simplemente se oscurece',
    'Трансляция с телефона на ТВ: уберите, если не выводите видео с телефона': 'Transmisión del móvil a la TV: quítala si no envías vídeo desde el móvil',
    'YouTube: уберите, только если смотрите его в другом приложении': 'YouTube: quítalo solo si lo ves en otra app',
    'Браузер: уберите, если не открываете сайты на телевизоре': 'Navegador: quítalo si no abres webs en la TV',
    'Плеер для видео: если после удаления что-то перестанет играть, верните его в «Истории»': 'Reproductor de vídeo: si algo deja de reproducirse al quitarlo, devuélvelo en Historial',
    'Файлы и плеер для флешки: уберите, если не смотрите видео с USB': 'Archivos y reproductor USB: quítalo si no ves vídeos desde USB',
    'Фото и видео с флешки: уберите, если не смотрите их на ТВ': 'Fotos y vídeos desde USB: quítalo si no los ves en la TV',
    'Часть Alexa: уберите, если не пользуетесь голосовым помощником Amazon': 'Parte de Alexa: quítala si no usas el asistente de voz de Amazon',
    'Камера: на телевизоре без камеры не нужна': 'Cámara: no hace falta en una TV sin cámara',
    'Подключение часов и других гаджетов к ТВ; почти никому не нужно': 'Vincular relojes y otros dispositivos a la TV; casi nadie lo necesita',
    'Автонастройка прокси по PAC-файлу: нужна только в офисных сетях': 'Configuración automática de proxy por archivo PAC: solo hace falta en redes de oficina',
    'Аккаунт производителя (CVTE): нужен только для его фирменных сервисов': 'Cuenta del fabricante (CVTE): solo hace falta para sus propios servicios',
    'Синхронизация контактов: на ТВ бесполезна': 'Sincronización de contactos: inútil en una TV',
    'Корпоративное управление устройством: дома не нужно': 'Gestión corporativa del dispositivo: no hace falta en casa',
    'Экстренные оповещения через сотовую сеть: на ТВ без SIM-карты не работают': 'Alertas de emergencia por la red móvil: no funcionan en una TV sin tarjeta SIM',
    'HbbTV: интерактивные кнопки эфирных каналов. Сами каналы работают и без него': 'HbbTV: botones interactivos de los canales de TDT. Los canales funcionan sin él',
    'Убирают в {0} из {1} списков чистки ТВ': 'Se quita en {0} de {1} listas de limpieza de TV',
    'Можно убрать: телевизор без этого работает': 'Se puede quitar: la TV funciona sin esto',
    'На ваше усмотрение: уберите, только если не пользуетесь этой функцией': 'A tu criterio: quítalo solo si no usas esta función',
    'Лучше оставить': 'Mejor dejarlo',
    'Системное: TVCleanzer его не трогает': 'Del sistema: TVCleanzer no lo toca',
    'Занимает {0} МБ': 'Ocupa {0} MB',
    'Понятно': 'Entendido',
    'Не знаете, что это? Нажмите на значок слева или удерживайте строку.': '¿No sabes qué es? Toca el icono de la izquierda o mantén pulsada la fila.',
    'Вид главного экрана': 'Estilo de la pantalla principal',
    'Плитки': 'Mosaicos',
    'Часы и док': 'Reloj y dock',
    'Размер часов': 'Tamaño del reloj',
    'Меньше': 'Más pequeño',
    'Крупнее': 'Más grande',
    'Огромные': 'Enorme',
    'Шрифт часов': 'Fuente del reloj',
    'Тонкий': 'Fina',
    'Лёгкий': 'Ligera',
    'Обычный': 'Normal',
    'Узкий': 'Estrecha',
    'Жирный': 'Negrita',
    'Часы на экране': 'Posición del reloj',
    'Слева': 'Izquierda',
    'По центру': 'Centro',
    'Погода на главном экране': 'Tiempo en la pantalla principal',
    'Выключена — нажмите, чтобы выбрать город': 'Desactivado: toca para elegir una ciudad',
    'Город для погоды': 'Ciudad para el tiempo',
    'Например, Оренбург': 'Por ejemplo, Madrid',
    'Ничего не нашлось': 'No se encontró nada',
    'Нет интернета на телефоне': 'No hay internet en el teléfono',
    'Не показывать погоду': 'No mostrar el tiempo',
    'Погоду телевизор берёт с Open-Meteo раз в полчаса; о вас туда ничего не отправляется.': 'La TV obtiene el tiempo de Open-Meteo cada media hora; no se envía nada sobre ti.',
    'Выключить': 'Desactivar',
    'Выключить отладку на ТВ': 'Desactivar la depuración en la TV',
    'Выключить отладку на телевизоре?': '¿Desactivar la depuración en la TV?',
    'Так безопаснее: к телевизору больше никто не подключится по сети. Чтобы снова пользоваться TVCleanzer, включите отладку на ТВ так же, как в первый раз.': 'Es más seguro: nadie más podrá conectarse a la TV por la red. Para volver a usar TVCleanzer, activa la depuración en la TV igual que la primera vez.',
    'Отладка на телевизоре выключена': 'La depuración en la TV está desactivada',
    'Готово: кнопка «Домой» открывает TVCleanzer Launcher.': 'Listo: el botón Inicio abre TVCleanzer Launcher.',
    'Готово: прошивка возвращала свой лаунчер, поэтому он убран (вернётся кнопкой «Вернуть стандартный лаунчер»). Кнопка «Домой» открывает TVCleanzer Launcher.': 'Listo: el firmware volvía a poner su launcher, así que se ha quitado («Restaurar el launcher estándar» lo devuelve). El botón Inicio abre TVCleanzer Launcher.',
    'Готово: свой лаунчер прошивки остаётся, но кнопку «Домой» и экран при включении перехватывает TVCleanzer Launcher.': 'Listo: el launcher del firmware se queda, pero TVCleanzer Launcher toma el botón Inicio y la pantalla al encender.',
    'Лаунчер стоит, но телевизор не даёт сделать его главным: «Домой» открывает свой экран. Нажмите «Сделать главным ещё раз»; если не поможет — откройте лаунчер из списка приложений ТВ и пришлите отчёт через «?».': 'El launcher está instalado, pero la TV no deja ponerlo como principal: Inicio abre su propia pantalla. Toca «Hacerlo principal otra vez»; si no ayuda, abre el launcher desde la lista de apps de la TV y envía un informe con «?».',
    'Источники (HDMI)': 'Entradas (HDMI)',
    'Вверху': 'Arriba',
    'Внизу': 'Abajo',
    'Скрыты': 'Ocultas',
    'Лаунчер установлен, но главный экран сейчас другой — прошивка его вернула. Нажмите «Сделать главным ещё раз».': 'El launcher está instalado, pero ahora la pantalla principal es otra: el firmware la recuperó. Toca «Hacerlo principal otra vez».',
    'Сделать главным ещё раз': 'Hacerlo principal otra vez',
    'При включении ТВ открывать': 'Al encender la TV, abrir',
    'Главный экран (лаунчер)': 'Pantalla principal (launcher)',
    'При включении откроется главный экран': 'Al encender se abrirá la pantalla principal',
    'При включении откроется «{0}»': 'Al encender se abrirá «{0}»',
    'Например, YouTube или онлайн-кинотеатр: включили телевизор — и сразу в нём. Кнопка «Домой» по-прежнему ведёт в лаунчер.': 'Por ejemplo, YouTube o un servicio de streaming: enciendes la TV y estás directamente en él. El botón Inicio sigue llevando al launcher.',
    'Эта настройка появилась в новой версии лаунчера: обновите его на вкладке «Лаунчер».': 'Este ajuste llega con la nueva versión del launcher: actualízalo en la pestaña Launcher.',
    'Проверяем кнопку «Домой»…': 'Comprobando el botón Inicio…',
    'Закрепляем лаунчер…': 'Fijando el launcher…',
    'Ещё': 'Más',
    'Убрать из списка': 'Quitar de la lista',
    'Нет двоеточия на клавиатуре? Поставьте после адреса точку или запятую — TVCleanzer сам заменит её на «:».': '¿No hay dos puntos en el teclado? Pon un punto o una coma después de la dirección: TVCleanzer lo cambia por «:».',
    'На Яндекс ТВ TVCleanzer отключает приложения, а не удаляет: так их не вернут обновления. Главный экран Яндекса, аккаунт, Кинопоиск и входы HDMI он не трогает. Если в меню разработчика нет раздела «Отладка» — смотрите вкладку «Нет отладки».': 'En Yandex TV, TVCleanzer desactiva las apps en lugar de desinstalarlas, así las actualizaciones no las devuelven. Nunca toca la pantalla principal de Yandex, la cuenta, Kinopoisk ni las entradas HDMI. Si en Opciones de desarrollador no hay sección de depuración, mira la pestaña «Sin depuración».',
    'Нет отладки': 'Sin depuración',
    'TUVIO, SunWind, Hi, Leff и другие на плате CVTE: меню разработчика есть, а раздела «Отладка» в нём нет': 'TUVIO, SunWind, Hi, Leff y otros con placa CVTE: hay Opciones de desarrollador, pero sin sección de depuración',
    'Сначала просто запустите поиск в TVCleanzer: на части таких телевизоров отладка по сети включена с завода, хотя в меню её не видно.': 'Primero simplemente busca en TVCleanzer: en algunos de estos televisores la depuración por red viene activada de fábrica, aunque el menú no la muestre.',
    'Не нашёлся? Откройте Настройки → «Изображение», наведите на «Контраст» и наберите на пульте 1147. Не открылось — попробуйте 9735.': '¿No aparece? Abre Ajustes → Imagen, sitúate en Contraste y marca 1147 en el mando. Si no se abre nada, prueba 9735.',
    'В открывшемся сервисном меню зайдите в Debug (или Other) и включите ADB Enable. Перезагрузите телевизор и запустите поиск в TVCleanzer.': 'En el menú de servicio que se abre, entra en Debug (u Other) y activa ADB Enable. Reinicia la TV y vuelve a buscar en TVCleanzer.',
    'Код не сработал или в меню нет ADB: скачайте маленькое приложение FactoryMenu (com.stb.factorymenu, тема о платах CVTE на 4PDA), установите его с флешки через «Файлы», откройте → Debug → ADB Enable.': '¿El código no funcionó o el menú no tiene ADB? Descarga la pequeña app FactoryMenu (com.stb.factorymenu, del hilo sobre placas CVTE en el foro 4PDA), instálala desde un USB con Archivos y ábrela → Debug → ADB Enable.',
    'В сервисном меню меняйте только ADB: там же настройки матрицы, подсветки и заводской режим. На таких телевизорах отладка может пускать любого в сети без вопроса — когда закончите, выключите ADB там же или перезагрузите ТВ.': 'En el menú de servicio cambia solo ADB: ahí también están los ajustes del panel, la retroiluminación y el modo de fábrica. En estos televisores la depuración puede dejar entrar a cualquiera de la red sin preguntar: al terminar, desactiva ADB ahí mismo o reinicia la TV.',
    'Не удалось прочитать файл. Сохраните его в «Файлы» и попробуйте снова.': 'No se pudo leer el archivo. Guárdalo en Archivos e inténtalo de nuevo.',
    'Готовим {0}…': 'Preparando {0}…',
    'Установлено: {0}. Его можно открыть кнопкой ниже.': 'Instalado: {0}. Puedes abrirlo con el botón de abajo.',
    'Связь с телевизором прервалась. Попробуйте ещё раз.': 'Se perdió la conexión con la TV. Inténtalo de nuevo.',
    'Открыли «{0}» на телевизоре': 'Se abrió «{0}» en la TV',
    '«{0}» не открывается: у него нет экрана запуска.': '«{0}» no se puede abrir: no tiene pantalla de inicio.',
    'Телевизор не отвечает.': 'La TV no responde.',
    'Удалить «{0}»?': '¿Desinstalar «{0}»?',
    'Приложение и его данные будут удалены с телевизора. Вернуть можно только установкой заново.': 'La app y sus datos se eliminarán de la TV. Solo se recupera reinstalándola.',
    'Удалить': 'Desinstalar',
    '«{0}» удалено': '«{0}» desinstalada',
    'Телевизор не дал удалить «{0}».': 'La TV no permitió desinstalar «{0}».',
    'НА ТЕЛЕВИЗОРЕ': 'EN LA TV',
    'Телевизор не показал ни одного приложения.': 'La TV no mostró ninguna app.',
    'Установить приложение из файла': 'Instalar una app desde un archivo',
    'Скачайте APK на телефон (например, SmartTube или Кинопоиск для ТВ) и выберите его здесь — TVCleanzer поставит его на телевизор. Нужно для Яндекс ТВ, Сбера и других телевизоров без Google Play. Подходят .apk, .apks и .xapk.': 'Descarga un APK en el teléfono (por ejemplo, SmartTube) y elígelo aquí: TVCleanzer lo instala en la TV. Útil en televisores sin Google Play, como Yandex TV y Sber. Sirven .apk, .apks y .xapk.',
    'Выбрать файл APK': 'Elegir archivo APK',
    'Ставьте приложения только из источников, которым доверяете.': 'Instala apps solo de fuentes de confianza.',
    'Открыть': 'Abrir',
    'Это не файл приложения Android (.apk).': 'No es un archivo de app Android (.apk).',
    'В этом файле нет приложения Android (.apk).': 'Este archivo no contiene ninguna app Android (.apk).',
    'Отправляем на телевизор {0} МБ…': 'Enviando {0} MB a la TV…',
    'Отправляем часть {0} из {1}…': 'Enviando parte {0} de {1}…',
    'Устанавливаем…': 'Instalando…',
    'На телевизоре уже стоит это приложение с другой подписью. Удалите его в списке ниже и установите снова.': 'La TV ya tiene esta app con otra firma. Desinstálala en la lista de abajo e instálala de nuevo.',
    'Эта сборка не подходит для процессора телевизора. Скачайте версию armeabi-v7a (или universal).': 'Esta versión no es compatible con el procesador de la TV. Descarga la versión armeabi-v7a (o universal).',
    'Приложению нужна более новая версия Android, чем на телевизоре.': 'La app necesita una versión de Android más nueva que la de la TV.',
    'На телевизоре уже стоит более новая версия. Удалите её в списке ниже, если нужна именно эта.': 'La TV ya tiene una versión más nueva. Desinstálala en la lista de abajo si necesitas esta.',
    'На телевизоре не хватает места. Сначала сделайте очистку.': 'No hay espacio suficiente en la TV. Haz primero una limpieza.',
    'Файл повреждён или это не приложение Android.': 'El archivo está dañado o no es una app Android.',
    'Настройки': 'Ajustes',
    'Салют ТВ': 'Salute TV',
    'Каталог приложений Сбера': 'Catálogo de apps de Sber',
    'Кинопоиск': 'Kinopoisk',
    'ES Проводник': 'ES File Explorer',
    'Яндекс ТВ': 'Yandex TV',
    'Салют ТВ (Сбер)': 'Salute TV (Sber)',
    'Сбер': 'Sber',
    'Телевизоры с Алисой: Hi, Leff, Tuvio, Haier, Hyundai, Artel, SunWind и другие (YaOS)': 'Televisores con Alice: Hi, Leff, Tuvio, Haier, Hyundai, Artel, SunWind y otros (YaOS)',
    'Откройте Настройки (шестерёнка на главном экране) → «Устройство» или «Настройки устройства».': 'Abre Ajustes (el engranaje de la pantalla principal) → «Dispositivo» o «Preferencias del dispositivo».',
    'На Яндекс ТВ TVCleanzer отключает приложения, а не удаляет: так их не вернут обновления. Главный экран Яндекса, аккаунт, Кинопоиск и входы HDMI он не трогает. Если пункта отладки в меню разработчика нет (так бывает на части моделей на плате CVTE), остаётся только сервисное меню — без опыта лучше туда не заходить.': 'En Yandex TV, TVCleanzer desactiva las apps en lugar de desinstalarlas, así las actualizaciones no las devuelven. Nunca toca la pantalla principal de Yandex, la cuenta, Kinopoisk ni las entradas HDMI. Si en Opciones de desarrollador no hay depuración (algunos modelos con placa CVTE), solo queda el menú de servicio: mejor no entrar sin experiencia.',
    'Телевизоры Sber и SberBox с Салют ТВ (StarOS)': 'Televisores Sber y SberBox con Salute TV (StarOS)',
    'Откройте Настройки → «Об устройстве».': 'Abre Ajustes → «Información».',
    'Меню разработчика не появляется? У Сбера есть свой переключатель: войдите на developers.sber.ru в SmartApp Studio тем же Сбер ID, что и на телевизоре, откройте «Мои устройства», добавьте ТВ по серийному номеру из «Об устройстве» и включите ADB. Раздел SmartApp появляется, когда в личном пространстве есть хотя бы один проект — создайте пустой. Срабатывает не на всех моделях.': '¿No aparecen las Opciones de desarrollador? Sber tiene su propio interruptor: entra en SmartApp Studio en developers.sber.ru con el mismo Sber ID que en la TV, abre «Mis dispositivos», añade la TV con el número de serie de «Información» y activa ADB. La sección SmartApp solo aparece si tu espacio personal tiene al menos un proyecto: crea uno vacío. No funciona en todos los modelos.',
    'На Салют ТВ TVCleanzer отключает приложения, а не удаляет: удалённые Сбер ставит обратно. Часть из них (СберПрайм, реклама умного дома, настройка провайдеров) прошивка включает снова после перезагрузки — просто повторите очистку. Каталог приложений Сбера, ассистент Салют и входы HDMI TVCleanzer не трогает.': 'En Salute TV, TVCleanzer desactiva las apps en lugar de desinstalarlas: Sber reinstala las desinstaladas. El firmware vuelve a activar algunas (SberPrime, anuncios del hogar inteligente, configuración de proveedores) tras reiniciar: basta con repetir la limpieza. TVCleanzer nunca toca el catálogo de apps de Sber, el asistente Salute ni las entradas HDMI.',
