    'Связь с телевизором прервалась во время очистки.': 'Se perdió la conexión con la TV durante la limpieza.',
    'Ошибка: {0}': 'Error: {0}',
    'Очистка': 'Limpiar',
    'Приложения будут скрыты, а не удалены навсегда. Восстановить их можно в любой момент.': 'Las apps se ocultarán, no se borrarán para siempre. Puedes restaurarlas cuando quieras.',
    '{0} приложений будут скрыты': 'Se ocultarán {0} apps',
    'Освободится ~{0} МБ': 'Se liberarán ~{0} MB',
    'Отмена': 'Cancelar',
    'Очистить': 'Limpiar',
    'Убираем {0} из {1}…': 'Quitando {0} de {1}…',
    'Завершаем…': 'Terminando…',
    'Ошибка очистки': 'Error en la limpieza',
    'Назад': 'Atrás',
    'Повторить': 'Reintentar',
    'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки': 'Haier, Hartens, Sony, TCL, Kivi, DEXP, decodificadores',
    'Откройте Настройки → «Настройки устройства» (на части моделей — «Система»).': 'Abre Ajustes → «Preferencias del dispositivo» (en algunos modelos, «Sistema»).',
    'Зайдите в «Об устройстве».': 'Entra en «Información».',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Selecciona «Compilación» y pulsa OK en el mando 7 veces seguidas: aparecerá «Ahora eres desarrollador».',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Vuelve atrás: ha aparecido «Opciones para desarrolladores». Ábrela.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Activa «Depuración por USB». Si hay «Depuración por red» o «ADB por red», actívala también.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Sony, TCL, Hisense nuevos, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Ajustes → «Sistema» → «Información».',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Pulsa OK 7 veces en «Compilación del SO Android TV».',
    'Назад в «Система» → «Для разработчиков».': 'Vuelve a «Sistema» → «Opciones para desarrolladores».',
    'Включите «Отладка по USB».': 'Activa «Depuración por USB».',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'Si no se encuentra la TV: activa allí también «Depuración inalámbrica» y en TVCleanzer pulsa «Conectar con código» (el icono con números arriba en la pantalla principal).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'La conexión con código solo se hace una vez. Funciona en teléfonos con Android 10 o superior (mejor 12+) y en iPhone.',
    'Глобальная прошивка с PatchWall / Android TV': 'Firmware global con PatchWall / Android TV',
    'Настройки → «Настройки устройства» → «Об устройстве».': 'Ajustes → «Preferencias del dispositivo» → «Información».',
    'Нажмите ОК 7 раз на строке «Сборка».': 'Pulsa OK 7 veces en «Compilación».',
    'Назад → «Для разработчиков» → включите «Отладка по USB».': 'Atrás → «Opciones para desarrolladores» → activa «Depuración por USB».',
    'Xiaomi Китай': 'Xiaomi China',
    'Redmi и Xiaomi с китайской прошивкой (HyperOS, MIUI TV)': 'Redmi y Xiaomi con firmware chino (HyperOS, MIUI TV)',
    'Настройки → «О телевизоре».': 'Ajustes → «Acerca de la TV».',
    'Нажмите ОК 7 раз на строке «Модель продукта».': 'Pulsa OK 7 veces en «Modelo de producto».',
    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Atrás → «Cuenta y seguridad» → activa «Depuración ADB».',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'En estos firmwares la depuración se apaga tras cada reinicio de la TV: actívala antes de usar TVCleanzer.',
    'Amazon Fire TV и телевизоры с Fire OS': 'Amazon Fire TV y televisores con Fire OS',
    'Настройки → «Моё Fire TV» → «О программе».': 'Ajustes → «Mi Fire TV» → «Información».',
    'Нажмите ОК 7 раз на названии устройства.': 'Pulsa OK 7 veces en el nombre del dispositivo.',
    'Назад → «Для разработчиков» → включите «Отладка ADB».': 'Atrás → «Opciones para desarrolladores» → activa «Depuración ADB».',
    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'Fire OS no permite cambiar la pantalla de inicio: la limpieza y el mando funcionan, nuestro launcher no.',
    'Android TV и Google TV от Philips': 'Android TV y Google TV de Philips',
    'Проверьте Настройки → «Об устройстве»: если там есть версия Android (прошивка TPM…), делайте как для Android TV.': 'Mira Ajustes → «Información»: si aparece una versión de Android (firmware TPM…), sigue los pasos de Android TV.',
    'Прошивки TPN… (Titan OS, Saphi) — не Android, с ними TVCleanzer не работает.': 'Los firmwares TPN… (Titan OS, Saphi) no son Android; TVCleanzer no funciona con ellos.',
    'а также Hisense VIDAA, Roku': 'y también Hisense VIDAA, Roku',
    'Это не Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.': 'No son Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.',
    'Отладки по сети на них нет, поэтому TVCleanzer с ними не работает.': 'No tienen depuración por red, así que TVCleanzer no funciona con ellos.',
    'Как включить отладку': 'Cómo activar la depuración',
    'Выберите свой телевизор:': 'Elige tu TV:',
    'Телефон и телевизор должны быть в одной Wi-Fi сети. При первом подключении на ТВ появится «Разрешить отладку?» — отметьте «Всегда разрешать» и нажмите «Разрешить».': 'El teléfono y la TV deben estar en la misma red Wi-Fi. En la primera conexión la TV preguntará «¿Permitir depuración?»: marca «Permitir siempre» y pulsa «Permitir».',
