    'Вывод скопирован': 'Saída copiada',
    'Отчёт для чата': 'Relatório para o chat',
    'Отчёт с выводом терминала скопирован: вставьте его в чат': 'Relatório com a saída do terminal copiado: cole-o no chat',
    'Очистить экран': 'Limpar ecrã',
    'Осторожно': 'Cuidado',
    'Эта команда — {0}.': 'Este comando é {0}.',
    'Выполнить её на телевизоре?': 'Executá-lo na TV?',
    'Выполнить': 'Executar',
    'сброс или перезагрузка в служебный режим': 'uma reposição ou reinício num modo de serviço',
    'запись прямо на диск телевизора': 'uma escrita direta no armazenamento da TV',
    'удаление файлов без возможности вернуть': 'uma eliminação de ficheiros sem volta',
    'сброс системных настроек': 'uma reposição de definições do sistema',
    'постоянное изменение свойств прошивки': 'uma alteração permanente de propriedades do firmware',
    'системное приложение {0}: без него телевизор может не работать': 'sobre a app do sistema {0}: a TV pode não funcionar sem ela',
    'полное удаление приложения: вернуть его можно будет только установкой заново': 'uma desinstalação completa: a app só volta se for instalada de novo',
    'данные приложения будут стёрты': 'uma eliminação dos dados da app',
    'Модель': 'Modelo',
    'Свои приложения': 'Apps instaladas',
    'Отключённые': 'Desativadas',
    'Главный экран': 'Ecrã inicial',
    'Память': 'Memória',
    'Место': 'Espaço',
    'Кто ест память': 'Quem gasta memória',
    'Температура': 'Temperatura',
    'Ошибки (logcat)': 'Erros (logcat)',
    'Приложения на втором экране': 'Apps no segundo ecrã',
    'На главном только избранное, приложения — ниже по кнопке ▼': 'No início só os favoritos; as apps ficam abaixo, prima ▼',
    'Открыть на ТВ': 'Abrir na TV',
    'Прошивка не даёт убрать их с телефона. Нажмите «Открыть на ТВ» и на телевизоре выберите «Отключить».': 'O firmware não deixa removê-las pelo telemóvel. Toque em «Abrir na TV» e, na TV, escolha «Desativar».',
    'На телевизоре открылись настройки приложения: выберите «Отключить».': 'Na TV abriram-se as definições da app: escolha «Desativar».',
    'Не получилось открыть настройки на ТВ': 'Não foi possível abrir as definições na TV',
    'Спасибо! Это очень помогает делать TVCleanzer дальше.': 'Obrigado! Isto ajuda muito a continuar o TVCleanzer.',
    'Чаевые разработчику: ничего не открывают и не продлеваются — просто спасибо за приложение.': 'Uma gorjeta para o programador: não desbloqueia nada nem se renova — é só um obrigado pela app.',
    'Включать, когда телевизор простоит': 'Ligar quando a TV estiver parada há',
    'Показать сейчас': 'Mostrar agora',
    'Фоторамка запущена на телевизоре': 'A moldura de fotos está a correr na TV',
    'Телевизор не дал запустить заставку сразу: она включится сама, когда ТВ постоит без дела.': 'A TV não deixou iniciar a proteção de ecrã já: vai iniciar sozinha quando a TV estiver parada.',
    'Автор — {0} · {1}': 'Autor: {0} · {1}',
    'TVCleanzer бесплатный и без рекламы. Если он вам помог — можно поддержать автора.': 'O TVCleanzer é gratuito e sem anúncios. Se ajudou, pode apoiar o autor.',
    'Поддержать автора': 'Apoiar o autor',
    'Спасибо! Любая сумма помогает делать TVCleanzer дальше.': 'Obrigado! Qualquer valor ajuda a continuar o TVCleanzer.',
    'Ссылка скопирована: {0}': 'Link copiado: {0}',
    '{0} мин': '{0} min',
    '{0} с': '{0} s',
    'Ваши фото по очереди, с часами и погодой: когда телевизор простаивает, и, если хотите, фоном главного экрана. Включается только по вашему желанию.': 'As suas fotos uma após outra, com a hora e a meteorologia: quando a TV está parada e, se quiser, como fundo do ecrã principal. Só liga se quiser.',
    'Вернуть прежнюю заставку': 'Repor a proteção de ecrã anterior',
    'До 30 фото. Они уменьшаются до 1920 пикселей и занимают немного места.': 'Até 30 fotos. São reduzidas para 1920 píxeis e ocupam pouco espaço.',
    'Добавить фото': 'Adicionar fotos',
    'Менять фон главного экрана': 'Mudar o fundo do ecrã principal',
    'На телевизоре фото: {0}': 'Fotos na TV: {0}',
    'Отправляем фото {0} из {1}…': 'A enviar a foto {0} de {1}…',
    'Прежняя заставка возвращена': 'A proteção de ecrã anterior foi reposta',
    'Сделать заставкой телевизора': 'Usar como proteção de ecrã da TV',
    'Сейчас заставка телевизора — фоторамка': 'A proteção de ecrã da TV é agora a moldura de fotos',
    'Смена фото': 'Mudança de foto',
    'Сохранено': 'Guardado',
    'Удалить все': 'Apagar todas',
    'Фото добавлены: {0}': 'Fotos adicionadas: {0}',
    'Фото сменяют друг друга вместо одного фона': 'As fotos alternam em vez de um só fundo',
    'Фото удалены': 'Fotos apagadas',
    'Фоторамка': 'Moldura de fotos',
    'Фоторамка включена: она появится, когда телевизор постоит без дела. Через сколько минут — задаётся в настройках ТВ, раздел «Заставка».': 'Moldura de fotos ligada: aparece quando a TV fica parada algum tempo. Os minutos definem-se nas definições da TV, secção Proteção de ecrã.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+; на Android 5–6 — пробная поддержка).': 'Um launcher leve e bonito: relógio, favoritos, todas as apps, temas. Menos de 100 KB, funciona até em TVs fracas (Android 7+; Android 5–6 experimental).',
    'Нужен Android 5 или новее на телевизоре (сейчас SDK {0}).': 'A TV precisa do Android 5 ou mais recente (agora SDK {0}).',
    'Избранное на главном экране': 'Favoritos no ecrã principal',
    'Один ряд': 'Uma fila',
    'По 4': '4 por fila',
    'По 5': '5 por fila',
    'По 6': '6 por fila',
    'Погоду телевизор берёт с Open-Meteo или met.no раз в полчаса; о вас туда ничего не отправляется.': 'A TV obtém a meteorologia do Open-Meteo ou do met.no a cada meia hora; nada sobre si é enviado.',
    'Убираем PatchWall…': 'A remover o PatchWall…',
    'телевизор не может получить погоду: проверьте, что на нём есть интернет': 'a TV não consegue obter a meteorologia: verifique se tem internet',
    'Обычное приложение: уберите, если не пользуетесь': 'App normal: remova-a se não a usa',
    'Онлайн-кинотеатр: уберите, если нет подписки и не смотрите': 'Serviço de streaming: remova-o se não tem subscrição nem o vê',
    'Музыка: уберите, если не слушаете музыку на телевизоре': 'Música: remova-a se não ouve música na TV',
    'Заставка, когда ТВ простаивает. Без неё будет просто тёмный экран': 'Proteção de ecrã quando a TV está parada. Sem ela, o ecrã fica apenas escuro',
    'Трансляция с телефона на ТВ: уберите, если не выводите видео с телефона': 'Transmissão do telemóvel para a TV: remova-a se não envia vídeo do telemóvel',
    'YouTube: уберите, только если смотрите его в другом приложении': 'YouTube: remova-o só se o vê noutra app',
    'Браузер: уберите, если не открываете сайты на телевизоре': 'Navegador: remova-o se não abre sites na TV',
    'Плеер для видео: если после удаления что-то перестанет играть, верните его в «Истории»': 'Leitor de vídeo: se algo deixar de reproduzir depois de o remover, devolva-o no Histórico',
    'Файлы и плеер для флешки: уберите, если не смотрите видео с USB': 'Ficheiros e leitor USB: remova-o se não vê vídeos por USB',
    'Фото и видео с флешки: уберите, если не смотрите их на ТВ': 'Fotos e vídeos de USB: remova-o se não os vê na TV',
    'Часть Alexa: уберите, если не пользуетесь голосовым помощником Amazon': 'Parte da Alexa: remova-a se não usa o assistente de voz da Amazon',
    'Камера: на телевизоре без камеры не нужна': 'Câmara: não é precisa numa TV sem câmara',
    'Подключение часов и других гаджетов к ТВ; почти никому не нужно': 'Ligar relógios e outros dispositivos à TV; quase ninguém precisa',
    'Автонастройка прокси по PAC-файлу: нужна только в офисных сетях': 'Configuração automática de proxy por ficheiro PAC: só é precisa em redes de escritório',
    'Аккаунт производителя (CVTE): нужен только для его фирменных сервисов': 'Conta do fabricante (CVTE): só é precisa para os serviços dele',
    'Синхронизация контактов: на ТВ бесполезна': 'Sincronização de contactos: inútil numa TV',
    'Корпоративное управление устройством: дома не нужно': 'Gestão empresarial do dispositivo: não é precisa em casa',
    'Экстренные оповещения через сотовую сеть: на ТВ без SIM-карты не работают': 'Alertas de emergência pela rede móvel: não funcionam numa TV sem cartão SIM',
    'HbbTV: интерактивные кнопки эфирных каналов. Сами каналы работают и без него': 'HbbTV: botões interativos dos canais de TDT. Os canais funcionam sem ele',
    'Убирают в {0} из {1} списков чистки ТВ': 'Removida em {0} de {1} listas de limpeza de TV',
    'Можно убрать: телевизор без этого работает': 'Pode remover: a TV funciona sem isto',
    'На ваше усмотрение: уберите, только если не пользуетесь этой функцией': 'À sua escolha: remova-o só se não usa esta função',
    'Лучше оставить': 'Melhor manter',
    'Системное: TVCleanzer его не трогает': 'Do sistema: o TVCleanzer não lhe mexe',
    'Занимает {0} МБ': 'Ocupa {0} MB',
    'Понятно': 'Entendido',
    'Не знаете, что это? Нажмите на значок слева или удерживайте строку.': 'Não sabe o que é? Toque no ícone à esquerda ou mantenha a linha premida.',
    'Вид главного экрана': 'Estilo do ecrã principal',
    'Плитки': 'Mosaicos',
    'Часы и док': 'Relógio e dock',
    'Размер часов': 'Tamanho do relógio',
    'Меньше': 'Menor',
    'Крупнее': 'Maior',
    'Огромные': 'Enorme',
    'Шрифт часов': 'Tipo de letra do relógio',
    'Тонкий': 'Fino',
    'Лёгкий': 'Leve',
    'Обычный': 'Normal',
    'Узкий': 'Estreito',
    'Жирный': 'Negrito',
    'Часы на экране': 'Posição do relógio',
    'Слева': 'Esquerda',
    'По центру': 'Centro',
    'Погода на главном экране': 'Meteorologia no ecrã principal',
    'Выключена — нажмите, чтобы выбрать город': 'Desligado — toque para escolher uma cidade',
    'Город для погоды': 'Cidade para a meteorologia',
    'Например, Оренбург': 'Por exemplo, Lisboa',
    'Ничего не нашлось': 'Nada encontrado',
    'Нет интернета на телефоне': 'Sem internet no telemóvel',
    'Не показывать погоду': 'Não mostrar a meteorologia',
    'Погоду телевизор берёт с Open-Meteo раз в полчаса; о вас туда ничего не отправляется.': 'A TV obtém a meteorologia do Open-Meteo a cada meia hora; nada sobre si é enviado.',
    'Выключить': 'Desligar',
    'Выключить отладку на ТВ': 'Desligar a depuração na TV',
    'Выключить отладку на телевизоре?': 'Desligar a depuração na TV?',
    'Так безопаснее: к телевизору больше никто не подключится по сети. Чтобы снова пользоваться TVCleanzer, включите отладку на ТВ так же, как в первый раз.': 'É mais seguro: mais ninguém se liga à TV pela rede. Para voltar a usar o TVCleanzer, ligue a depuração na TV da mesma forma que da primeira vez.',
    'Отладка на телевизоре выключена': 'A depuração na TV está desligada',
    'Готово: кнопка «Домой» открывает TVCleanzer Launcher.': 'Pronto: o botão Início abre o TVCleanzer Launcher.',
    'Готово: прошивка возвращала свой лаунчер, поэтому он убран (вернётся кнопкой «Вернуть стандартный лаунчер»). Кнопка «Домой» открывает TVCleanzer Launcher.': 'Pronto: o firmware voltava a pôr o seu launcher, por isso foi removido («Restaurar o launcher padrão» devolve-o). O botão Início abre o TVCleanzer Launcher.',
    'Готово: свой лаунчер прошивки остаётся, но кнопку «Домой» и экран при включении перехватывает TVCleanzer Launcher.': 'Pronto: o launcher do firmware fica, mas o TVCleanzer Launcher assume o botão Início e o ecrã ao ligar.',
    'Лаунчер стоит, но телевизор не даёт сделать его главным: «Домой» открывает свой экран. Нажмите «Сделать главным ещё раз»; если не поможет — откройте лаунчер из списка приложений ТВ и пришлите отчёт через «?».': 'O launcher está instalado, mas a TV não deixa torná-lo principal: Início abre o seu próprio ecrã. Toque em «Torná-lo principal outra vez»; se não ajudar, abra o launcher na lista de apps da TV e envie um relatório através de «?».',
    'Источники (HDMI)': 'Entradas (HDMI)',
    'Вверху': 'Em cima',
    'Внизу': 'Em baixo',
    'Скрыты': 'Ocultas',
    'Лаунчер установлен, но главный экран сейчас другой — прошивка его вернула. Нажмите «Сделать главным ещё раз».': 'O launcher está instalado, mas o ecrã principal agora é outro — o firmware recuperou-o. Toque em «Torná-lo principal outra vez».',
    'Сделать главным ещё раз': 'Torná-lo principal outra vez',
    'При включении ТВ открывать': 'Ao ligar a TV, abrir',
    'Главный экран (лаунчер)': 'Ecrã principal (launcher)',
    'При включении откроется главный экран': 'Ao ligar abre o ecrã principal',
    'При включении откроется «{0}»': 'Ao ligar abre «{0}»',
    'Например, YouTube или онлайн-кинотеатр: включили телевизор — и сразу в нём. Кнопка «Домой» по-прежнему ведёт в лаунчер.': 'Por exemplo, o YouTube ou um serviço de streaming: liga a TV e está logo nele. O botão Início continua a levar ao launcher.',
    'Эта настройка появилась в новой версии лаунчера: обновите его на вкладке «Лаунчер».': 'Esta definição chega com a nova versão do launcher: atualize-o no separador Launcher.',
    'Проверяем кнопку «Домой»…': 'A verificar o botão Início…',
    'Закрепляем лаунчер…': 'A fixar o launcher…',
    'Ещё': 'Mais',
    'Убрать из списка': 'Remover da lista',
    'Нет двоеточия на клавиатуре? Поставьте после адреса точку или запятую — TVCleanzer сам заменит её на «:».': 'Não há dois pontos no teclado? Escreva um ponto ou uma vírgula depois do endereço — o TVCleanzer troca-o por «:».',
    'На Яндекс ТВ TVCleanzer отключает приложения, а не удаляет: так их не вернут обновления. Главный экран Яндекса, аккаунт, Кинопоиск и входы HDMI он не трогает. Если в меню разработчика нет раздела «Отладка» — смотрите вкладку «Нет отладки».': 'Na Yandex TV, o TVCleanzer desativa as apps em vez de as desinstalar, para que as atualizações não as tragam de volta. Nunca mexe no ecrã inicial da Yandex, na conta, no Kinopoisk nem nas entradas HDMI. Se as Opções de programador não tiverem a secção de depuração, veja o separador «Sem depuração».',
    'Нет отладки': 'Sem depuração',
    'TUVIO, SunWind, Hi, Leff и другие на плате CVTE: меню разработчика есть, а раздела «Отладка» в нём нет': 'TUVIO, SunWind, Hi, Leff e outros com placa CVTE: há Opções de programador, mas sem a secção de depuração',
    'Сначала просто запустите поиск в TVCleanzer: на части таких телевизоров отладка по сети включена с завода, хотя в меню её не видно.': 'Primeiro, basta procurar no TVCleanzer: em algumas destas TVs a depuração por rede vem ligada de fábrica, mesmo que o menu não a mostre.',
    'Не нашёлся? Откройте Настройки → «Изображение», наведите на «Контраст» и наберите на пульте 1147. Не открылось — попробуйте 9735.': 'Não foi encontrada? Abra Definições → Imagem, selecione Contraste e marque 1147 no comando. Se nada abrir, experimente 9735.',
    'В открывшемся сервисном меню зайдите в Debug (или Other) и включите ADB Enable. Перезагрузите телевизор и запустите поиск в TVCleanzer.': 'No menu de serviço que abrir, entre em Debug (ou Other) e ative ADB Enable. Reinicie a TV e procure novamente no TVCleanzer.',
    'Код не сработал или в меню нет ADB: скачайте маленькое приложение FactoryMenu (com.stb.factorymenu, тема о платах CVTE на 4PDA), установите его с флешки через «Файлы», откройте → Debug → ADB Enable.': 'O código não funcionou ou o menu não tem ADB? Descarregue a pequena app FactoryMenu (com.stb.factorymenu, do tópico sobre placas CVTE no fórum 4PDA), instale-a a partir de uma pen USB através de Ficheiros e abra-a → Debug → ADB Enable.',
    'В сервисном меню меняйте только ADB: там же настройки матрицы, подсветки и заводской режим. На таких телевизорах отладка может пускать любого в сети без вопроса — когда закончите, выключите ADB там же или перезагрузите ТВ.': 'No menu de serviço altere apenas o ADB: lá também estão as definições do painel, da retroiluminação e o modo de fábrica. Nestas TVs a depuração pode deixar entrar qualquer pessoa da rede sem perguntar — quando terminar, desligue o ADB aí ou reinicie a TV.',
    'Не удалось прочитать файл. Сохраните его в «Файлы» и попробуйте снова.': 'Não foi possível ler o ficheiro. Guarde-o em Ficheiros e tente novamente.',
    'Готовим {0}…': 'A preparar {0}…',
    'Установлено: {0}. Его можно открыть кнопкой ниже.': 'Instalado: {0}. Pode abri-lo com o botão abaixo.',
    'Связь с телевизором прервалась. Попробуйте ещё раз.': 'A ligação à TV caiu. Tente novamente.',
    'Открыли «{0}» на телевизоре': '«{0}» aberto na TV',
    '«{0}» не открывается: у него нет экрана запуска.': '«{0}» não abre: não tem ecrã de arranque.',
    'Телевизор не отвечает.': 'A TV não responde.',
    'Удалить «{0}»?': 'Desinstalar «{0}»?',
    'Приложение и его данные будут удалены с телевизора. Вернуть можно только установкой заново.': 'A app e os seus dados serão removidos da TV. Só volta se for reinstalada.',
    'Удалить': 'Desinstalar',
    '«{0}» удалено': '«{0}» desinstalada',
    'Телевизор не дал удалить «{0}».': 'A TV não deixou desinstalar «{0}».',
    'НА ТЕЛЕВИЗОРЕ': 'NA TV',
    'Телевизор не показал ни одного приложения.': 'A TV não mostrou nenhuma app.',
    'Установить приложение из файла': 'Instalar uma app a partir de um ficheiro',
    'Скачайте APK на телефон (например, SmartTube или Кинопоиск для ТВ) и выберите его здесь — TVCleanzer поставит его на телевизор. Нужно для Яндекс ТВ, Сбера и других телевизоров без Google Play. Подходят .apk, .apks и .xapk.': 'Descarregue um APK para o telemóvel (por exemplo, SmartTube) e escolha-o aqui — o TVCleanzer instala-o na TV. Útil em TVs sem Google Play, como Yandex TV e Sber. Funcionam .apk, .apks e .xapk.',
    'Выбрать файл APK': 'Escolher ficheiro APK',
    'Ставьте приложения только из источников, которым доверяете.': 'Instale apps apenas de fontes em que confia.',
    'Открыть': 'Abrir',
    'Это не файл приложения Android (.apk).': 'Não é um ficheiro de app Android (.apk).',
    'В этом файле нет приложения Android (.apk).': 'Este ficheiro não contém nenhuma app Android (.apk).',
    'Отправляем на телевизор {0} МБ…': 'A enviar {0} MB para a TV…',
    'Отправляем часть {0} из {1}…': 'A enviar parte {0} de {1}…',
    'Устанавливаем…': 'A instalar…',
    'На телевизоре уже стоит это приложение с другой подписью. Удалите его в списке ниже и установите снова.': 'A TV já tem esta app com outra assinatura. Desinstale-a na lista abaixo e instale novamente.',
    'Эта сборка не подходит для процессора телевизора. Скачайте версию armeabi-v7a (или universal).': 'Esta versão não serve para o processador da TV. Descarregue a versão armeabi-v7a (ou universal).',
    'Приложению нужна более новая версия Android, чем на телевизоре.': 'A app precisa de uma versão do Android mais recente do que a da TV.',
    'На телевизоре уже стоит более новая версия. Удалите её в списке ниже, если нужна именно эта.': 'A TV já tem uma versão mais recente. Desinstale-a na lista abaixo se precisar desta.',
    'На телевизоре не хватает места. Сначала сделайте очистку.': 'Não há espaço suficiente na TV. Faça primeiro uma limpeza.',
    'Файл повреждён или это не приложение Android.': 'O ficheiro está danificado ou não é uma app Android.',
    'Настройки': 'Definições',
    'Салют ТВ': 'Salute TV',
    'Каталог приложений Сбера': 'Catálogo de apps da Sber',
    'Кинопоиск': 'Kinopoisk',
    'ES Проводник': 'ES File Explorer',
    'Яндекс ТВ': 'Yandex TV',
    'Салют ТВ (Сбер)': 'Salute TV (Sber)',
    'Сбер': 'Sber',
    'Телевизоры с Алисой: Hi, Leff, Tuvio, Haier, Hyundai, Artel, SunWind и другие (YaOS)': 'TVs com Alice: Hi, Leff, Tuvio, Haier, Hyundai, Artel, SunWind e outras (YaOS)',
    'Откройте Настройки (шестерёнка на главном экране) → «Устройство» или «Настройки устройства».': 'Abra Definições (a roda dentada no ecrã inicial) → «Dispositivo» ou «Preferências do dispositivo».',
    'На Яндекс ТВ TVCleanzer отключает приложения, а не удаляет: так их не вернут обновления. Главный экран Яндекса, аккаунт, Кинопоиск и входы HDMI он не трогает. Если пункта отладки в меню разработчика нет (так бывает на части моделей на плате CVTE), остаётся только сервисное меню — без опыта лучше туда не заходить.': 'Na Yandex TV, o TVCleanzer desativa as apps em vez de as desinstalar, para que as atualizações não as tragam de volta. Nunca mexe no ecrã inicial da Yandex, na conta, no Kinopoisk nem nas entradas HDMI. Se as Opções de programador não tiverem depuração (alguns modelos com placa CVTE), resta só o menu de serviço — sem experiência, é melhor não entrar.',
    'Телевизоры Sber и SberBox с Салют ТВ (StarOS)': 'TVs Sber e SberBox com Salute TV (StarOS)',
    'Откройте Настройки → «Об устройстве».': 'Abra Definições → «Acerca de».',
    'Меню разработчика не появляется? У Сбера есть свой переключатель: войдите на developers.sber.ru в SmartApp Studio тем же Сбер ID, что и на телевизоре, откройте «Мои устройства», добавьте ТВ по серийному номеру из «Об устройстве» и включите ADB. Раздел SmartApp появляется, когда в личном пространстве есть хотя бы один проект — создайте пустой. Срабатывает не на всех моделях.': 'As Opções de programador não aparecem? A Sber tem o seu próprio interruptor: entre no SmartApp Studio em developers.sber.ru com o mesmo Sber ID da TV, abra «Os meus dispositivos», adicione a TV pelo número de série de «Acerca de» e ative o ADB. A secção SmartApp só aparece quando o espaço pessoal tem pelo menos um projeto — crie um vazio. Não funciona em todos os modelos.',
    'На Салют ТВ TVCleanzer отключает приложения, а не удаляет: удалённые Сбер ставит обратно. Часть из них (СберПрайм, реклама умного дома, настройка провайдеров) прошивка включает снова после перезагрузки — просто повторите очистку. Каталог приложений Сбера, ассистент Салют и входы HDMI TVCleanzer не трогает.': 'Na Salute TV, o TVCleanzer desativa as apps em vez de as desinstalar: a Sber reinstala as desinstaladas. O firmware volta a ativar algumas (SberPrime, publicidade da casa inteligente, configuração de operadores) depois de reiniciar — basta repetir a limpeza. O TVCleanzer nunca mexe no catálogo de apps da Sber, no assistente Salute nem nas entradas HDMI.',
