    'Назад': 'Voltar',
    'Повторить': 'Tentar de novo',
    'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки': 'Haier, Hartens, Sony, TCL, Kivi, DEXP, boxes',
    'Откройте Настройки → «Настройки устройства» (на части моделей — «Система»).': 'Abra Definições → «Preferências do dispositivo» (nalguns modelos, «Sistema»).',
    'Зайдите в «Об устройстве».': 'Entre em «Acerca de».',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Selecione «Compilação» e prima OK no comando 7 vezes seguidas — aparece «Agora é um programador».',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Volte atrás: apareceu «Opções de programador». Abra-a.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Ative «Depuração USB». Se houver «Depuração de rede» ou «ADB pela rede», ative-a também.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Sony, TCL, Hisense recentes, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Definições → «Sistema» → «Acerca de».',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Prima OK 7 vezes em «Compilação do SO Android TV».',
    'Назад в «Система» → «Для разработчиков».': 'Volte a «Sistema» → «Opções de programador».',
    'Включите «Отладка по USB».': 'Ative «Depuração USB».',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'Se a TV não for encontrada: ative também «Depuração sem fios» e no TVCleanzer toque em «Ligar com código» (o ícone com números no topo do ecrã principal).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'A ligação com código só é precisa uma vez. Funciona em telemóveis com Android 10 ou superior (melhor 12+) e no iPhone.',
    'Глобальная прошивка с PatchWall / Android TV': 'Firmware global com PatchWall / Android TV',
    'Настройки → «Настройки устройства» → «Об устройстве».': 'Definições → «Preferências do dispositivo» → «Acerca de».',
    'Нажмите ОК 7 раз на строке «Сборка».': 'Prima OK 7 vezes em «Compilação».',
    'Назад → «Для разработчиков» → включите «Отладка по USB».': 'Voltar → «Opções de programador» → ative «Depuração USB».',
    'Xiaomi Китай': 'Xiaomi China',
    'Redmi и Xiaomi с китайской прошивкой (HyperOS, MIUI TV)': 'Redmi e Xiaomi com firmware chinês (HyperOS, MIUI TV)',
    'Настройки → «О телевизоре».': 'Definições → «Acerca da TV».',
    'Нажмите ОК 7 раз на строке «Модель продукта».': 'Prima OK 7 vezes em «Modelo do produto».',
    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Voltar → «Conta e segurança» → ative «Depuração ADB».',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'Nestes firmwares a depuração desliga-se após cada reinício da TV — ative-a antes de usar o TVCleanzer.',
    'Amazon Fire TV и телевизоры с Fire OS': 'Amazon Fire TV e televisores com Fire OS',
    'Настройки → «Моё Fire TV» → «О программе».': 'Definições → «O meu Fire TV» → «Acerca de».',
    'Нажмите ОК 7 раз на названии устройства.': 'Prima OK 7 vezes no nome do dispositivo.',
    'Назад → «Для разработчиков» → включите «Отладка ADB».': 'Voltar → «Opções de programador» → ative «Depuração ADB».',
    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'O Fire OS não deixa mudar o ecrã inicial: a limpeza e o comando funcionam, o nosso launcher não.',
    'Android TV и Google TV от Philips': 'Android TV e Google TV da Philips',
    'Проверьте Настройки → «Об устройстве»: если там есть версия Android (прошивка TPM…), делайте как для Android TV.': 'Veja Definições → «Acerca de»: se mostrar uma versão do Android (firmware TPM…), siga os passos de Android TV.',
    'Прошивки TPN… (Titan OS, Saphi) — не Android, с ними TVCleanzer не работает.': 'Os firmwares TPN… (Titan OS, Saphi) não são Android; o TVCleanzer não funciona com eles.',
    'а также Hisense VIDAA, Roku': 'e também Hisense VIDAA, Roku',
    'Это не Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.': 'Não são Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.',
    'Отладки по сети на них нет, поэтому TVCleanzer с ними не работает.': 'Não têm depuração de rede, por isso o TVCleanzer não funciona com eles.',
    'Как включить отладку': 'Como ativar a depuração',
    'Выберите свой телевизор:': 'Escolha a sua TV:',
    'Телефон и телевизор должны быть в одной Wi-Fi сети. При первом подключении на ТВ появится «Разрешить отладку?» — отметьте «Всегда разрешать» и нажмите «Разрешить».': 'O telemóvel e a TV têm de estar na mesma rede Wi-Fi. Na primeira ligação a TV pergunta «Permitir depuração?» — marque «Permitir sempre» e toque em «Permitir».',
    'Как включить отладку на ТВ': 'Como ativar a depuração na TV',
    'Пошагово для вашего бренда': 'Passo a passo para a sua marca',
    'Сообщить о проблеме': 'Comunicar um problema',
    'Скопирует модель ТВ и журнал ошибок': 'Copia o modelo da TV e o registo de erros',
    'Скопировано. Вставьте в чат TVCleanzer в Telegram и допишите, что случилось.': 'Copiado. Cole no chat do TVCleanzer no Telegram e conte o que aconteceu.',
