    'Шкурка меняется сразу: просто выберите другую выше. На телевизоре: долгое нажатие OK на приложении — добавить в избранное, переставить или скрыть; шестерёнка — настройки.': 'O tema muda logo: escolha outro acima. Na TV: mantenha OK premido numa app para a adicionar aos favoritos, mover ou ocultar; a roda dentada abre as definições.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+).': 'Um launcher leve e bonito: relógio, favoritos, todas as apps, temas. Menos de 100 KB, funciona até em TVs fracas (Android 7+).',
