    'На ТВ: Настройки → Для разработчиков → Беспроводная отладка → ВКЛ → «Подключить устройство с помощью кода». Введите адрес и код из этого окна.': 'Na TV: Definições → Opções de programador → Depuração sem fios → LIGADA → «Sincronizar dispositivo com código». Introduza o endereço e o código dessa janela.',
