  'de': {
    'связь восстановлена': 'Verbindung wiederhergestellt',
    'Связь прервалась. Подключаемся снова…': 'Verbindung unterbrochen. Verbinde erneut…',
    'Google Play выключен': 'Google Play ist ausgeschaltet',
    'Google Play есть в прошивке телевизора, но выключен или скрыт. Его не нужно ставить из файла: достаточно включить.': 'Google Play ist in der Firmware des Fernsehers, aber aus- oder ausgeblendet. Keine Installation aus einer Datei nötig: einfach einschalten.',
    'Включить Google Play': 'Google Play einschalten',
    'Google Play снова включён на телевизоре.': 'Google Play ist auf dem Fernseher wieder an.',
    'Не получилось включить Google Play: прошивка не даёт. Подробности — в отчёте «?».': 'Google Play ließ sich nicht einschalten: die Firmware erlaubt es nicht. Details im „?“-Bericht.',
    'Терминал': 'Terminal',
    'терминал': 'Terminal',
    'Терминал (для разработчиков)': 'Terminal (für Entwickler)',
    'Для разработчиков': 'Für Entwickler',
    'Терминал отправляет команды на телевизор напрямую, как «adb shell» с компьютера. TVCleanzer их не проверяет и не может отменить: неверная команда может сломать прошивку или стереть данные.': 'Das Terminal schickt Befehle direkt an den Fernseher, wie „adb shell“ vom Computer. TVCleanzer prüft sie nicht und kann sie nicht rückgängig machen: Ein falscher Befehl kann die Firmware beschädigen oder Daten löschen.',
    'Пользуйтесь, только если понимаете, что делаете. Всё — на ваш страх и риск.': 'Nur verwenden, wenn du weißt, was du tust. Alles auf eigene Gefahr.',
    'Я понимаю и беру ответственность на себя': 'Ich verstehe es und übernehme die Verantwortung',
