    'Файлы и плеер для флешки: уберите, если не смотрите видео с USB': 'Dateien und USB-Player: entfernen, wenn Sie keine Videos vom USB-Stick schauen',
    'Фото и видео с флешки: уберите, если не смотрите их на ТВ': 'Fotos und Videos vom USB-Stick: entfernen, wenn Sie sie nicht am TV ansehen',
    'Часть Alexa: уберите, если не пользуетесь голосовым помощником Amazon': 'Teil von Alexa: entfernen, wenn Sie Amazons Sprachassistenten nicht nutzen',
    'Камера: на телевизоре без камеры не нужна': 'Kamera: auf einem TV ohne Kamera unnötig',
    'Подключение часов и других гаджетов к ТВ; почти никому не нужно': 'Uhren und andere Geräte mit dem TV koppeln; braucht fast niemand',
    'Автонастройка прокси по PAC-файлу: нужна только в офисных сетях': 'Automatische Proxy-Einrichtung per PAC-Datei: nur in Büronetzen nötig',
    'Аккаунт производителя (CVTE): нужен только для его фирменных сервисов': 'Herstellerkonto (CVTE): nur für dessen eigene Dienste nötig',
    'Синхронизация контактов: на ТВ бесполезна': 'Kontaktsynchronisierung: am TV nutzlos',
    'Корпоративное управление устройством: дома не нужно': 'Firmen-Geräteverwaltung: zu Hause unnötig',
    'Экстренные оповещения через сотовую сеть: на ТВ без SIM-карты не работают': 'Notfallwarnungen über das Mobilfunknetz: funktionieren am TV ohne SIM-Karte nicht',
    'HbbTV: интерактивные кнопки эфирных каналов. Сами каналы работают и без него': 'HbbTV: interaktive Tasten für Sender. Die Sender selbst laufen auch ohne',
    'Убирают в {0} из {1} списков чистки ТВ': 'Entfernt in {0} von {1} TV-Aufräumlisten',
    'Можно убрать: телевизор без этого работает': 'Kann weg: Der TV funktioniert ohne',
    'На ваше усмотрение: уберите, только если не пользуетесь этой функцией': 'Ihre Entscheidung: nur entfernen, wenn Sie diese Funktion nicht nutzen',
