    'Эти настройки появились в новой версии лаунчера: нажмите «Обновить лаунчер на ТВ» ниже.': 'Diese Einstellungen kommen mit der neuen Launcher-Version: unten auf „Launcher auf dem TV aktualisieren“ tippen.',
    'Слабый телевизор подтормаживает? Выключите анимации и живой фон.': 'Ein schwacher TV ruckelt? Animationen und lebendigen Hintergrund ausschalten.',
    'Есть новая версия лаунчера: тонкие настройки, живой фон, новые шкурки и надёжная загрузка фото. Нажмите «Обновить лаунчер на ТВ».': 'Neue Launcher-Version verfügbar: Feineinstellungen, lebendiger Hintergrund, neue Designs und zuverlässiger Foto-Upload. Auf „Launcher auf dem TV aktualisieren“ tippen.',
    'Затемнение фото': 'Foto abdunkeln',
    'Затемнение работает в новой версии лаунчера: обновите его на вкладке «Лаунчер».': 'Das Abdunkeln braucht die neue Launcher-Version: im Tab „Launcher“ aktualisieren.',
    'Лучше горизонтальное фото, 16:9. Затемнение помогает читать часы и названия на ярких снимках.': 'Am besten ein Querformat-Foto in 16:9. Abdunkeln hält Uhr und Namen auf hellen Bildern lesbar.',
    'Отправляем фото на телевизор…': 'Foto wird an den TV gesendet…',
    'Не удалось прочитать фото. Выберите другое.': 'Foto konnte nicht gelesen werden. Wähle ein anderes.',
    'Фото не дошло до телевизора целиком. Попробуйте ещё раз.': 'Das Foto kam nicht vollständig am TV an. Bitte erneut versuchen.',
    'Телевизор не дал сохранить фото. Обновите лаунчер на ТВ и попробуйте снова.': 'Der TV hat das Speichern des Fotos verweigert. Launcher auf dem TV aktualisieren und erneut versuchen.',
    'Проекторы': 'Beamer',
    'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — на Android TV и Google TV': 'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — mit Android TV und Google TV',
    'На Google TV: если проектор не находится, включите там же «Беспроводная отладка» и подключите TVCleanzer по коду.': 'Bei Google TV: Wird der Beamer nicht gefunden, dort auch „Wireless-Debugging“ einschalten und TVCleanzer per Code verbinden.',
    'Автотрапецию, фокус и настройки проекции TVCleanzer не трогает.': 'Trapezkorrektur, Fokus und Projektionseinstellungen fasst TVCleanzer nie an.',
    'Проекторы HY300': 'HY300-Beamer',
    'Magcubic, Allwinner, Rockchip и похожие китайские модели': 'Magcubic, Allwinner, Rockchip und ähnliche chinesische Modelle',
    'Откройте Настройки → «Other settings» (или «Система») → «Developer mode» / «Для разработчиков».': 'Öffne Einstellungen → „Other settings“ (oder „System“) → „Developer mode“ / „Entwickleroptionen“.',
    'Включите «ADB debug» или «Отладка по USB». Если есть «Беспроводная отладка» — включите её и подключите TVCleanzer по коду.': '„ADB debug“ oder „USB-Debugging“ einschalten. Gibt es „Wireless-Debugging“, dieses einschalten und TVCleanzer per Code verbinden.',
    'На многих таких проекторах отладка выключается после перезагрузки — включайте её перед работой с TVCleanzer. Автофокус и трапецию TVCleanzer не трогает.': 'Bei vielen dieser Beamer schaltet sich das Debugging nach einem Neustart ab — vor TVCleanzer wieder einschalten. Autofokus und Trapezkorrektur fasst TVCleanzer nie an.',
    'Полночь': 'Mitternacht',
    'Аврора': 'Aurora',
    'Закат': 'Sonnenuntergang',
    'Океан': 'Ozean',
    'Графит': 'Graphit',
    'Лес': 'Wald',
    'Связь с телевизором прервалась во время очистки.': 'Die Verbindung zum Fernseher brach während der Bereinigung ab.',
    'Ошибка: {0}': 'Fehler: {0}',
    'Очистка': 'Bereinigen',
    'Приложения будут скрыты, а не удалены навсегда. Восстановить их можно в любой момент.': 'Apps werden ausgeblendet, nicht endgültig gelöscht. Sie lassen sich jederzeit wiederherstellen.',
    '{0} приложений будут скрыты': '{0} Apps werden ausgeblendet',
    'Освободится ~{0} МБ': 'Es werden ~{0} MB frei',
    'Отмена': 'Abbrechen',
    'Очистить': 'Bereinigen',
    'Убираем {0} из {1}…': 'Entferne {0} von {1}…',
    'Завершаем…': 'Abschließen…',
    'Ошибка очистки': 'Bereinigung fehlgeschlagen',
    'Назад': 'Zurück',
    'Повторить': 'Erneut versuchen',
    'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки': 'Haier, Hartens, Sony, TCL, Kivi, DEXP, Set-Top-Boxen',
    'Откройте Настройки → «Настройки устройства» (на части моделей — «Система»).': 'Öffne Einstellungen → „Geräteeinstellungen“ (bei manchen Modellen „System“).',
    'Зайдите в «Об устройстве».': 'Öffne „Info“.',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Markiere „Build“ und drücke 7-mal hintereinander OK auf der Fernbedienung — es erscheint „Du bist jetzt Entwickler“.',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Geh zurück: Der Punkt „Entwickleroptionen“ ist erschienen. Öffne ihn.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Schalte „USB-Debugging“ ein. Gibt es „Netzwerk-Debugging“ oder „ADB über Netzwerk“, schalte es auch ein.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Neuere Sony, TCL, Hisense, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Einstellungen → „System“ → „Info“.',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Drücke 7-mal OK auf „Android TV OS-Build“.',
    'Назад в «Система» → «Для разработчиков».': 'Zurück zu „System“ → „Entwickleroptionen“.',
    'Включите «Отладка по USB».': 'Schalte „USB-Debugging“ ein.',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'Wird der Fernseher nicht gefunden: Schalte dort auch „Wireless-Debugging“ ein und tippe in TVCleanzer auf „Per Code verbinden“ (Symbol mit Ziffern oben auf dem Startbildschirm).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'Die Kopplung per Code ist nur einmal nötig. Funktioniert auf Handys mit Android 10 oder neuer (am besten 12+) und auf dem iPhone.',
    'Глобальная прошивка с PatchWall / Android TV': 'Globale Firmware mit PatchWall / Android TV',
    'Настройки → «Настройки устройства» → «Об устройстве».': 'Einstellungen → „Geräteeinstellungen“ → „Info“.',
    'Нажмите ОК 7 раз на строке «Сборка».': 'Drücke 7-mal OK auf „Build“.',
    'Назад → «Для разработчиков» → включите «Отладка по USB».': 'Zurück → „Entwickleroptionen“ → „USB-Debugging“ einschalten.',
    'Xiaomi Китай': 'Xiaomi China',
    'Redmi и Xiaomi с китайской прошивкой (HyperOS, MIUI TV)': 'Redmi und Xiaomi mit chinesischer Firmware (HyperOS, MIUI TV)',
    'Настройки → «О телевизоре».': 'Einstellungen → „Über den Fernseher“.',
    'Нажмите ОК 7 раз на строке «Модель продукта».': 'Drücke 7-mal OK auf „Produktmodell“.',
    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Zurück → „Konto & Sicherheit“ → „ADB-Debugging“ einschalten.',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'Bei dieser Firmware schaltet sich Debugging nach jedem Neustart des Fernsehers aus — schalte es vor der Nutzung von TVCleanzer ein.',
    'Amazon Fire TV и телевизоры с Fire OS': 'Amazon Fire TV und Fernseher mit Fire OS',
    'Настройки → «Моё Fire TV» → «О программе».': 'Einstellungen → „Mein Fire TV“ → „Info“.',
    'Нажмите ОК 7 раз на названии устройства.': 'Drücke 7-mal OK auf den Gerätenamen.',
    'Назад → «Для разработчиков» → включите «Отладка ADB».': 'Zurück → „Entwickleroptionen“ → „ADB-Debugging“ einschalten.',
    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'Fire OS lässt den Startbildschirm nicht ändern: Bereinigung und Fernbedienung funktionieren, unser Launcher nicht.',
    'Android TV и Google TV от Philips': 'Android TV und Google TV von Philips',
    'Проверьте Настройки → «Об устройстве»: если там есть версия Android (прошивка TPM…), делайте как для Android TV.': 'Sieh unter Einstellungen → „Info“ nach: Steht dort eine Android-Version (Firmware TPM…), folge den Schritten für Android TV.',
    'Прошивки TPN… (Titan OS, Saphi) — не Android, с ними TVCleanzer не работает.': 'TPN…-Firmware (Titan OS, Saphi) ist kein Android; TVCleanzer funktioniert damit nicht.',
    'а также Hisense VIDAA, Roku': 'sowie Hisense VIDAA, Roku',
    'Это не Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.': 'Das ist kein Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.',
    'Отладки по сети на них нет, поэтому TVCleanzer с ними не работает.': 'Sie haben kein Netzwerk-Debugging, deshalb funktioniert TVCleanzer damit nicht.',
    'Как включить отладку': 'Debugging einschalten',
    'Выберите свой телевизор:': 'Wähle deinen Fernseher:',
    'Телефон и телевизор должны быть в одной Wi-Fi сети. При первом подключении на ТВ появится «Разрешить отладку?» — отметьте «Всегда разрешать» и нажмите «Разрешить».': 'Handy und Fernseher müssen im selben WLAN sein. Bei der ersten Verbindung fragt der Fernseher „Debugging zulassen?“ — hake „Immer zulassen“ an und tippe auf „Zulassen“.',
