    'Узнаем, какой лаунчер сейчас главный на «{0}».': 'Wir prüfen, welcher Launcher auf „{0}“ der Hauptlauncher ist.',
    'Главный лаунчер не выбран: телевизор спрашивает при нажатии «Домой».': 'Kein Hauptlauncher festgelegt: Der Fernseher fragt beim Drücken von „Home“.',
