    'установлен': 'installiert',
    'не установлен': 'nicht installiert',
    'Шкурка меняется сразу: просто выберите другую выше. На телевизоре: долгое нажатие OK на приложении — добавить в избранное, переставить или скрыть; шестерёнка — настройки.': 'Das Design wechselt sofort: Wähle einfach oben ein anderes. Auf dem Fernseher: OK auf einer App lange drücken — zu Favoriten hinzufügen, verschieben oder ausblenden; das Zahnrad öffnet die Einstellungen.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+).': 'Ein leichter, schöner Launcher: Uhr, Favoriten, alle Apps, Designs. Unter 100 KB, läuft sogar auf schwachen Fernsehern (Android 7+).',
