    'Введите адрес как на экране ТВ, например 192.168.1.20:37155': 'Gib die Adresse wie auf dem TV ein, z. B. 192.168.1.20:37155',
    'Код — 6 цифр из окна «Подключение по коду».': 'Der Code sind die 6 Ziffern aus dem Fenster „Mit Code koppeln“.',
