    'Не удалось подключиться. Проверьте порт: он на главном экране «Беспроводной отладки» и отличается от порта сопряжения.': 'Verbindung fehlgeschlagen. Prüfe den Port: Er steht auf dem Hauptbildschirm von „Wireless-Debugging“ und unterscheidet sich vom Kopplungsport.',
    'Сопряжение': 'Kopplung',
    'На ТВ: Настройки → Для разработчиков → Беспроводная отладка → ВКЛ → «Подключить устройство с помощью кода». Введите адрес и код из этого окна.': 'Am TV: Einstellungen → Entwickleroptionen → Wireless-Debugging → AN → „Gerät über einen Kopplungscode koppeln“. Gib Adresse und Code aus diesem Fenster ein.',
    'IP-адрес и порт': 'IP-Adresse und Port',
