    'Лаунчер не ответил. Обновите его на ТВ кнопкой «Обновить лаунчер».': 'Der Launcher hat nicht geantwortet. Aktualisiere ihn am TV mit der Schaltfläche „Launcher aktualisieren“.',
    'На компьютере подключение по коду пока не работает. Включите на ТВ «Отладку по сети» (порт 5555) — такой ТВ найдётся сам — или подключите ТВ по коду с телефона.': 'Auf dem Computer funktioniert die Kopplung per Code noch nicht. Schalte am TV „Netzwerk-Debugging“ ein (Port 5555) — dann wird er automatisch gefunden — oder kopple den TV per Code vom Handy aus.',
    'Этот телефон не поддерживает сопряжение по коду.': 'Dieses Handy unterstützt keine Kopplung per Code.',
    'Не удалось подключиться к {0}:{1}. Проверьте адрес и порт в окне с кодом.': 'Verbindung zu {0}:{1} fehlgeschlagen. Prüfe Adresse und Port im Code-Fenster.',
    'Сопряжение не удалось. Проверьте код и что окно с кодом ещё открыто на ТВ.': 'Kopplung fehlgeschlagen. Prüfe den Code und ob das Code-Fenster am TV noch offen ist.',
    'Телевизор прислал странный ответ.': 'Der Fernseher hat eine merkwürdige Antwort geschickt.',
    'Неверный код. Проверьте шесть цифр на экране телевизора.': 'Falscher Code. Prüfe die sechs Ziffern auf dem Fernseher.',
    'Телевизор прервал сопряжение. Проверьте код и попробуйте снова.': 'Der Fernseher hat die Kopplung abgebrochen. Prüfe den Code und versuche es erneut.',
    'Нет связи с телевизором. Проверьте, что он включён и в той же Wi-Fi сети.': 'Keine Verbindung zum Fernseher. Prüfe, ob er eingeschaltet und im selben WLAN ist.',
