    'Эти настройки появились в новой версии лаунчера: нажмите «Обновить лаунчер на ТВ» ниже.': 'Ces réglages arrivent avec la nouvelle version du launcher : touchez « Mettre à jour le launcher sur le TV » ci-dessous.',
    'Слабый телевизор подтормаживает? Выключите анимации и живой фон.': 'Une TV peu puissante saccade ? Désactivez les animations et le fond animé.',
    'Есть новая версия лаунчера: тонкие настройки, живой фон, новые шкурки и надёжная загрузка фото. Нажмите «Обновить лаунчер на ТВ».': 'Une nouvelle version du launcher est disponible : réglages fins, fond animé, nouveaux thèmes et envoi de photos fiable. Touchez « Mettre à jour le launcher sur le TV ».',
    'Затемнение фото': 'Assombrir la photo',
    'Затемнение работает в новой версии лаунчера: обновите его на вкладке «Лаунчер».': 'L’assombrissement nécessite la nouvelle version du launcher : mettez-le à jour dans l’onglet « Launcher ».',
    'Лучше горизонтальное фото, 16:9. Затемнение помогает читать часы и названия на ярких снимках.': 'Une photo paysage 16:9 est idéale. L’assombrissement garde l’horloge et les noms lisibles sur les images claires.',
    'Отправляем фото на телевизор…': 'Envoi de la photo à la TV…',
    'Не удалось прочитать фото. Выберите другое.': 'Impossible de lire la photo. Choisissez-en une autre.',
    'Фото не дошло до телевизора целиком. Попробуйте ещё раз.': 'La photo n’est pas arrivée entière sur la TV. Réessayez.',
    'Телевизор не дал сохранить фото. Обновите лаунчер на ТВ и попробуйте снова.': 'La TV n’a pas permis d’enregistrer la photo. Mettez à jour le launcher sur la TV et réessayez.',
    'Проекторы': 'Vidéoprojecteurs',
    'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — на Android TV и Google TV': 'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — sous Android TV et Google TV',
    'На Google TV: если проектор не находится, включите там же «Беспроводная отладка» и подключите TVCleanzer по коду.': 'Sur Google TV : si le projecteur n’est pas trouvé, activez aussi « Débogage sans fil » et connectez TVCleanzer avec un code.',
    'Автотрапецию, фокус и настройки проекции TVCleanzer не трогает.': 'TVCleanzer ne touche jamais à la correction trapézoïdale, à la mise au point ni aux réglages de projection.',
    'Проекторы HY300': 'Projecteurs HY300',
    'Magcubic, Allwinner, Rockchip и похожие китайские модели': 'Magcubic, Allwinner, Rockchip et modèles chinois similaires',
    'Откройте Настройки → «Other settings» (или «Система») → «Developer mode» / «Для разработчиков».': 'Ouvrez Paramètres → « Other settings » (ou « Système ») → « Developer mode » / « Options pour les développeurs ».',
    'Включите «ADB debug» или «Отладка по USB». Если есть «Беспроводная отладка» — включите её и подключите TVCleanzer по коду.': 'Activez « ADB debug » ou « Débogage USB ». S’il y a « Débogage sans fil », activez-le et connectez TVCleanzer avec un code.',
    'На многих таких проекторах отладка выключается после перезагрузки — включайте её перед работой с TVCleanzer. Автофокус и трапецию TVCleanzer не трогает.': 'Sur beaucoup de ces projecteurs, le débogage se désactive au redémarrage : réactivez-le avant d’utiliser TVCleanzer. TVCleanzer ne touche jamais à l’autofocus ni à la correction trapézoïdale.',
