    'Haier, Hartens, Sony, TCL, Kivi, DEXP, приставки': 'Haier, Hartens, Sony, TCL, Kivi, DEXP, box TV',
    'Откройте Настройки → «Настройки устройства» (на части моделей — «Система»).': 'Ouvrez Paramètres → « Préférences de l’appareil » (sur certains modèles « Système »).',
    'Зайдите в «Об устройстве».': 'Ouvrez « À propos ».',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Placez-vous sur « Build » et appuyez 7 fois de suite sur OK — « Vous êtes maintenant développeur » s’affiche.',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Revenez en arrière : l’élément « Options pour les développeurs » est apparu. Ouvrez-le.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Activez « Débogage USB ». S’il y a « Débogage réseau » ou « ADB via le réseau », activez-le aussi.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Sony, TCL, Hisense récents, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Paramètres → « Système » → « À propos ».',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Appuyez 7 fois sur OK sur « Build de l’OS Android TV ».',
    'Назад в «Система» → «Для разработчиков».': 'Retour dans « Système » → « Options pour les développeurs ».',
    'Включите «Отладка по USB».': 'Activez « Débogage USB ».',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'Si le téléviseur n’est pas trouvé : activez aussi « Débogage sans fil » et dans TVCleanzer touchez « Connecter avec un code » (l’icône avec des chiffres en haut de l’écran principal).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'L’association par code ne se fait qu’une fois. Fonctionne sur les téléphones Android 10 ou plus récents (idéalement 12+) et sur iPhone.',
    'Глобальная прошивка с PatchWall / Android TV': 'Firmware global avec PatchWall / Android TV',
    'Настройки → «Настройки устройства» → «Об устройстве».': 'Paramètres → « Préférences de l’appareil » → « À propos ».',
    'Нажмите ОК 7 раз на строке «Сборка».': 'Appuyez 7 fois sur OK sur « Build ».',
    'Назад → «Для разработчиков» → включите «Отладка по USB».': 'Retour → « Options pour les développeurs » → activez « Débogage USB ».',
