    'Настройки → «О телевизоре».': 'Paramètres → « À propos du téléviseur ».',
    'Нажмите ОК 7 раз на строке «Модель продукта».': 'Appuyez 7 fois sur OK sur « Modèle du produit ».',
    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Retour → « Compte et sécurité » → activez « Débogage ADB ».',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'Sur ces firmwares, le débogage se désactive à chaque redémarrage du téléviseur — activez-le avant d’utiliser TVCleanzer.',
    'Amazon Fire TV и телевизоры с Fire OS': 'Amazon Fire TV et téléviseurs sous Fire OS',
    'Настройки → «Моё Fire TV» → «О программе».': 'Paramètres → « Mon Fire TV » → « À propos ».',
    'Нажмите ОК 7 раз на названии устройства.': 'Appuyez 7 fois sur OK sur le nom de l’appareil.',
    'Назад → «Для разработчиков» → включите «Отладка ADB».': 'Retour → « Options pour les développeurs » → activez « Débogage ADB ».',
    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'Fire OS ne permet pas de changer l’écran d’accueil : le nettoyage et la télécommande fonctionnent, notre launcher non.',
    'Android TV и Google TV от Philips': 'Android TV et Google TV de Philips',
    'Проверьте Настройки → «Об устройстве»: если там есть версия Android (прошивка TPM…), делайте как для Android TV.': 'Vérifiez Paramètres → « À propos » : s’il y a une version d’Android (firmware TPM…), suivez les étapes Android TV.',
    'Прошивки TPN… (Titan OS, Saphi) — не Android, с ними TVCleanzer не работает.': 'Les firmwares TPN… (Titan OS, Saphi) ne sont pas Android ; TVCleanzer ne fonctionne pas avec eux.',
    'а также Hisense VIDAA, Roku': 'ainsi que Hisense VIDAA, Roku',
    'Это не Android: Samsung — Tizen, LG — webOS, Hisense — VIDAA.': 'Ce n’est pas Android : Samsung — Tizen, LG — webOS, Hisense — VIDAA.',
    'Отладки по сети на них нет, поэтому TVCleanzer с ними не работает.': 'Ils n’ont pas de débogage réseau, TVCleanzer ne fonctionne donc pas avec eux.',
    'Как включить отладку': 'Activer le débogage',
    'Выберите свой телевизор:': 'Choisissez votre téléviseur :',
    'Телефон и телевизор должны быть в одной Wi-Fi сети. При первом подключении на ТВ появится «Разрешить отладку?» — отметьте «Всегда разрешать» и нажмите «Разрешить».': 'Le téléphone et le téléviseur doivent être sur le même réseau Wi-Fi. À la première connexion, le téléviseur demande « Autoriser le débogage ? » — cochez « Toujours autoriser » et touchez « Autoriser ».',
