    'На ТВ останутся только выбранные приложения. Выйти — по PIN.': 'Seules les applis choisies resteront sur le TV. Sortie par code PIN.',
    'Новый PIN (необязательно)': 'Nouveau PIN (facultatif)',
    'PIN для выхода (4–8 цифр)': 'PIN de sortie (4 à 8 chiffres)',
    'Не настоящая блокировка: ребёнок, который знает про отладку, обойдёт её. Но от случайных приложений и рекламы — защитит.': 'Ce n’est pas un vrai verrou : un enfant qui connaît le débogage peut le contourner. Mais il protège des applis et publicités au hasard.',
