    'установлен': 'installé',
    'не установлен': 'non installé',
    'Шкурка меняется сразу: просто выберите другую выше. На телевизоре: долгое нажатие OK на приложении — добавить в избранное, переставить или скрыть; шестерёнка — настройки.': 'Le thème change instantanément : choisissez-en simplement un autre ci-dessus. Sur le téléviseur : appui long sur OK sur une appli pour l’ajouter aux favoris, la déplacer ou la masquer ; l’engrenage ouvre les réglages.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+).': 'Un launcher léger et élégant : horloge, favoris, toutes les applis, thèmes. Moins de 100 Ko, fonctionne même sur les téléviseurs modestes (Android 7+).',
