    'Не удалось подключиться. Проверьте порт: он на главном экране «Беспроводной отладки» и отличается от порта сопряжения.': 'Connexion impossible. Vérifiez le port : il figure sur l’écran principal de « Débogage sans fil » et diffère du port d’association.',
    'Сопряжение': 'Association',
    'На ТВ: Настройки → Для разработчиков → Беспроводная отладка → ВКЛ → «Подключить устройство с помощью кода». Введите адрес и код из этого окна.': 'Sur le TV : Paramètres → Options pour les développeurs → Débogage sans fil → ACTIVÉ → « Associer l’appareil avec un code ». Saisissez l’adresse et le code de cette fenêtre.',
    'IP-адрес и порт': 'Adresse IP et port',
