    'Подключение': 'Connexion',
    'Готово, телефон сопряжён. Окно с кодом можно закрыть. На главном экране «Беспроводной отладки» указан IP-адрес и порт — введите их.': 'C’est fait, le téléphone est associé. Vous pouvez fermer la fenêtre du code. L’écran principal de « Débogage sans fil » indique l’adresse IP et le port — saisissez-les.',
