  'it': {
    'связь восстановлена': 'connessione ripristinata',
    'Связь прервалась. Подключаемся снова…': 'Connessione persa. Riconnessione…',
    'Google Play выключен': 'Google Play è disattivato',
    'Google Play есть в прошивке телевизора, но выключен или скрыт. Его не нужно ставить из файла: достаточно включить.': 'Google Play è nel firmware della TV, ma disattivato o nascosto. Non serve installarlo da un file: basta attivarlo.',
    'Включить Google Play': 'Attiva Google Play',
    'Google Play снова включён на телевизоре.': 'Google Play è di nuovo attivo sulla TV.',
    'Не получилось включить Google Play: прошивка не даёт. Подробности — в отчёте «?».': 'Impossibile attivare Google Play: il firmware non lo consente. Dettagli nel rapporto «?».',
    'Терминал': 'Terminale',
    'терминал': 'terminale',
    'Терминал (для разработчиков)': 'Terminale (per sviluppatori)',
    'Для разработчиков': 'Per sviluppatori',
    'Терминал отправляет команды на телевизор напрямую, как «adb shell» с компьютера. TVCleanzer их не проверяет и не может отменить: неверная команда может сломать прошивку или стереть данные.': 'Il terminale invia i comandi direttamente alla TV, come «adb shell» da un computer. TVCleanzer non li controlla e non può annullarli: un comando sbagliato può rompere il firmware o cancellare i dati.',
    'Пользуйтесь, только если понимаете, что делаете. Всё — на ваш страх и риск.': 'Usalo solo se sai cosa stai facendo. Tutto a tuo rischio.',
    'Я понимаю и беру ответственность на себя': 'Ho capito e me ne assumo la responsabilità',
