    'По 6': '6 per fila',
    'Погоду телевизор берёт с Open-Meteo или met.no раз в полчаса; о вас туда ничего не отправляется.': 'La TV prende il meteo da Open-Meteo o met.no ogni mezz’ora; nulla su di te viene inviato.',
    'Убираем PatchWall…': 'Rimozione di PatchWall…',
    'телевизор не может получить погоду: проверьте, что на нём есть интернет': 'la TV non riesce a ottenere il meteo: verifica che abbia internet',
    'Обычное приложение: уберите, если не пользуетесь': 'App normale: rimuovila se non la usi',
    'Онлайн-кинотеатр: уберите, если нет подписки и не смотрите': 'Servizio di streaming: rimuovilo se non hai l’abbonamento e non lo guardi',
    'Музыка: уберите, если не слушаете музыку на телевизоре': 'Musica: rimuovila se non ascolti musica sulla TV',
    'Заставка, когда ТВ простаивает. Без неё будет просто тёмный экран': 'Salvaschermo quando la TV è inattiva. Senza, lo schermo diventa semplicemente scuro',
    'Трансляция с телефона на ТВ: уберите, если не выводите видео с телефона': 'Trasmissione dal telefono alla TV: rimuovila se non invii video dal telefono',
    'YouTube: уберите, только если смотрите его в другом приложении': 'YouTube: rimuovilo solo se lo guardi in un’altra app',
    'Браузер: уберите, если не открываете сайты на телевизоре': 'Browser: rimuovilo se non apri siti sulla TV',
    'Плеер для видео: если после удаления что-то перестанет играть, верните его в «Истории»': 'Lettore video: se dopo averlo rimosso qualcosa non si riproduce più, ripristinalo dalla Cronologia',
    'Файлы и плеер для флешки: уберите, если не смотрите видео с USB': 'File e lettore USB: rimuovilo se non guardi video da USB',
    'Фото и видео с флешки: уберите, если не смотрите их на ТВ': 'Foto e video da USB: rimuovilo se non li guardi sulla TV',
    'Часть Alexa: уберите, если не пользуетесь голосовым помощником Amazon': 'Parte di Alexa: rimuovila se non usi l’assistente vocale di Amazon',
    'Камера: на телевизоре без камеры не нужна': 'Fotocamera: inutile su una TV senza fotocamera',
    'Подключение часов и других гаджетов к ТВ; почти никому не нужно': 'Collegamento di orologi e altri dispositivi alla TV; non serve quasi a nessuno',
    'Автонастройка прокси по PAC-файлу: нужна только в офисных сетях': 'Configurazione automatica del proxy tramite file PAC: serve solo nelle reti aziendali',
    'Аккаунт производителя (CVTE): нужен только для его фирменных сервисов': 'Account del produttore (CVTE): serve solo per i suoi servizi',
    'Синхронизация контактов: на ТВ бесполезна': 'Sincronizzazione dei contatti: inutile su una TV',
    'Корпоративное управление устройством: дома не нужно': 'Gestione aziendale del dispositivo: non serve a casa',
    'Экстренные оповещения через сотовую сеть: на ТВ без SIM-карты не работают': 'Avvisi di emergenza tramite rete mobile: non funzionano su una TV senza SIM',
    'HbbTV: интерактивные кнопки эфирных каналов. Сами каналы работают и без него': 'HbbTV: pulsanti interattivi dei canali del digitale terrestre. I canali funzionano anche senza',
    'Убирают в {0} из {1} списков чистки ТВ': 'Rimossa in {0} di {1} elenchi di pulizia TV',
    'Можно убрать: телевизор без этого работает': 'Si può rimuovere: la TV funziona senza',
    'На ваше усмотрение: уберите, только если не пользуетесь этой функцией': 'A tua scelta: rimuovilo solo se non usi questa funzione',
    'Лучше оставить': 'Meglio tenerlo',
    'Системное: TVCleanzer его не трогает': 'Di sistema: TVCleanzer non lo tocca',
