    'Фото не дошло до телевизора целиком. Попробуйте ещё раз.': 'La foto non è arrivata completa alla TV. Riprova.',
    'Телевизор не дал сохранить фото. Обновите лаунчер на ТВ и попробуйте снова.': 'La TV non ha permesso di salvare la foto. Aggiorna il launcher sulla TV e riprova.',
    'Проекторы': 'Proiettori',
    'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — на Android TV и Google TV': 'XGIMI, Anker Nebula, BenQ, Epson, Formovie, Xiaomi, Wanbo — con Android TV e Google TV',
    'На Google TV: если проектор не находится, включите там же «Беспроводная отладка» и подключите TVCleanzer по коду.': 'Su Google TV: se il proiettore non viene trovato, attiva lì anche «Debug wireless» e collega TVCleanzer con un codice.',
    'Автотрапецию, фокус и настройки проекции TVCleanzer не трогает.': 'TVCleanzer non tocca mai la correzione trapezoidale, la messa a fuoco né le impostazioni di proiezione.',
    'Проекторы HY300': 'Proiettori HY300',
    'Magcubic, Allwinner, Rockchip и похожие китайские модели': 'Magcubic, Allwinner, Rockchip e modelli cinesi simili',
    'Откройте Настройки → «Other settings» (или «Система») → «Developer mode» / «Для разработчиков».': 'Apri Impostazioni → «Other settings» (o «Sistema») → «Developer mode» / «Opzioni sviluppatore».',
    'Включите «ADB debug» или «Отладка по USB». Если есть «Беспроводная отладка» — включите её и подключите TVCleanzer по коду.': 'Attiva «ADB debug» o «Debug USB». Se c’è «Debug wireless», attivalo e collega TVCleanzer con un codice.',
    'На многих таких проекторах отладка выключается после перезагрузки — включайте её перед работой с TVCleanzer. Автофокус и трапецию TVCleanzer не трогает.': 'Su molti di questi proiettori il debug si disattiva al riavvio: riattivalo prima di usare TVCleanzer. TVCleanzer non tocca mai l’autofocus né la correzione trapezoidale.',
