    'Зайдите в «Об устройстве».': 'Apri «Info».',
    'Наведите на строку «Сборка» и нажмите ОК на пульте 7 раз подряд — появится «Вы стали разработчиком».': 'Seleziona «Build» e premi OK sul telecomando 7 volte di fila: apparirà «Ora sei uno sviluppatore».',
    'Вернитесь назад: появился пункт «Для разработчиков». Откройте его.': 'Torna indietro: è comparsa la voce «Opzioni sviluppatore». Aprila.',
    'Включите «Отладка по USB». Если есть «Отладка по сети» или «ADB по сети» — включите и её.': 'Attiva «Debug USB». Se c’è «Debug di rete» o «ADB in rete», attiva anche quello.',
    'Новые Sony, TCL, Hisense, Chromecast': 'Sony, TCL, Hisense recenti, Chromecast',
    'Настройки → «Система» → «Об устройстве».': 'Impostazioni → «Sistema» → «Info».',
    'Нажмите ОК 7 раз на строке «Сборка ОС Android TV».': 'Premi OK 7 volte su «Build del sistema operativo Android TV».',
    'Назад в «Система» → «Для разработчиков».': 'Torna in «Sistema» → «Opzioni sviluppatore».',
    'Включите «Отладка по USB».': 'Attiva «Debug USB».',
    'Если телевизор не находится: там же включите «Беспроводная отладка» и в TVCleanzer нажмите «Подключить по коду» (значок с цифрами вверху главного экрана).': 'Se la TV non viene trovata: attiva lì anche «Debug wireless» e in TVCleanzer tocca «Connetti con codice» (l’icona con i numeri in alto nella schermata principale).',
    'Подключение по коду нужно один раз. Работает на телефонах с Android 10 и новее (лучше 12+) и на iPhone.': 'L’associazione con codice serve una sola volta. Funziona su telefoni con Android 10 o successivo (meglio 12+) e su iPhone.',
