    'Назад → «Аккаунт и безопасность» → включите «Отладка ADB».': 'Indietro → «Account e sicurezza» → attiva «Debug ADB».',
    'На этих прошивках отладка выключается после каждой перезагрузки телевизора — включайте её перед работой с TVCleanzer.': 'Su questi firmware il debug si disattiva a ogni riavvio della TV: attivalo prima di usare TVCleanzer.',
