    'Назад → «Для разработчиков» → включите «Отладка ADB».': 'Indietro → «Opzioni sviluppatore» → attiva «Debug ADB».',
    'Fire OS не даёт сменить главный экран: чистка и пульт работают, свой лаунчер — нет.': 'Fire OS non permette di cambiare la schermata Home: pulizia e telecomando funzionano, il nostro launcher no.',
    'Android TV и Google TV от Philips': 'Android TV e Google TV di Philips',
    'Проверьте Настройки → «Об устройстве»: если там есть версия Android (прошивка TPM…), делайте как для Android TV.': 'Controlla Impostazioni → «Info»: se c’è una versione di Android (firmware TPM…), segui i passaggi per Android TV.',
