    'Шкурка меняется сразу: просто выберите другую выше. На телевизоре: долгое нажатие OK на приложении — добавить в избранное, переставить или скрыть; шестерёнка — настройки.': 'Il tema cambia subito: scegline semplicemente un altro sopra. Sulla TV: tieni premuto OK su un’app per aggiungerla ai preferiti, spostarla o nasconderla; l’ingranaggio apre le impostazioni.',
    'Лёгкий красивый лаунчер: часы, избранное, все приложения, шкурки. Меньше 100 КБ, работает даже на слабых телевизорах (Android 7+).': 'Un launcher leggero ed elegante: orologio, preferiti, tutte le app, temi. Meno di 100 KB, funziona anche sulle TV meno potenti (Android 7+).',
